/* =============================================================================
 * HELPERS
 * ============================================================================= */

/** @internal */
function notificationValueToEncodedAccount<TAddress extends string>(
  address: Address<TAddress>,
  value: { data: [string, "base64"]; executable: boolean; lamports: Lamports; owner: Address },
): EncodedAccount<TAddress> {
  const data = base64ToUint8Array(value.data[0]);
  return {
    address,
    data,
    executable: value.executable,
    lamports: value.lamports,
    programAddress: value.owner,
    space: BigInt(data.length),
    exists: true,
  } as unknown as EncodedAccount<TAddress>;
}

/** @internal */
function checkAborted(signal: AbortSignal | undefined): void {
  if (signal?.aborted) {
    throw new ComputationMonitorError(
      "timeout",
      "Computation monitoring cancelled via AbortSignal",
    );
  }
}

/**
 * Fetches the current slot from the RPC.
 * @internal
 */
async function fetchCurrentSlot(
  rpc: ReturnType<typeof defaultCreateSolanaRpc>,
  commitment: Commitment,
): Promise<bigint> {
  const slot = await rpc.getSlot({ commitment }).send();
  return slot;
}

/**
 * Checks whether the slot window has been exceeded.
 * @internal
 */
function isSlotWindowExceeded(
  queuedSlot: bigint,
  currentSlot: bigint,
  maxSlotWindow: number,
): boolean {
  return currentSlot - queuedSlot > BigInt(maxSlotWindow);
}

/**
 * Retrieves the callback transaction signature after finalization.
 *
 * @throws {ComputationMonitorError} With stage `"signature-retrieval"`.
 * @internal
 */
async function retrieveCallbackTransactionSignature(
  rpc: ReturnType<typeof defaultCreateSolanaRpc>,
  computationAddress: Address,
): Promise<TransactionSignature> {
  try {
    const response = await rpc
      .getSignaturesForAddress(computationAddress, {
        limit: DEFAULT_SIGNATURE_RETRIEVAL_LIMIT,
      })
      .send();

    for (const entry of response) {
      if (entry.err === null) {
        const sig = entry.signature.toString();
        assertTransactionSignature(sig);
        return sig;
      }
    }

    throw new ComputationMonitorError(
      "signature-retrieval",
      `No successful callback transaction found (checked ${String(DEFAULT_SIGNATURE_RETRIEVAL_LIMIT)} signatures)`,
    );
  } catch (error) {
    if (error instanceof ComputationMonitorError) {
      throw error;
    }
    throw new ComputationMonitorError(
      "signature-retrieval",
      "Failed to retrieve callback transaction signature",
      error instanceof Error ? error : undefined,
    );
  }
}

/**
 * Builds a finalized result, optionally retrieving the callback signature.
 * @internal
 */
async function buildFinalizedResult(
  rpc: ReturnType<typeof defaultCreateSolanaRpc>,
  computationAddress: Address,
  startTime: number,
  queuedSlot: bigint,
  shouldRetrieveSignature: boolean,
  onProgress?: (event: ComputationMonitorProgressEvent) => void,
): Promise<ComputationFinalizedResult | ComputationFinalizedResultWithSignature> {
  const elapsedMs = Date.now() - startTime;

  if (shouldRetrieveSignature) {
    const callbackSignature = await retrieveCallbackTransactionSignature(rpc, computationAddress);
    onProgress?.({ type: "finalized", callbackSignature });
    return { status: "finalized", elapsedMs, queuedSlot, callbackSignature };
  }

  onProgress?.({ type: "finalized" });
  return { status: "finalized", elapsedMs, queuedSlot };
}

/**
 * Builds a pruned result.
 * @internal
 */
function buildPrunedResult(
  startTime: number,
  queuedSlot: bigint,
  currentSlot: bigint,
  onProgress?: (event: ComputationMonitorProgressEvent) => void,
): ComputationPrunedResult {
  onProgress?.({ type: "pruned", queuedSlot, currentSlot });
  return {
    status: "pruned",
    elapsedMs: Date.now() - startTime,
    queuedSlot,
    currentSlot,
  };
}

/**
 * Builds a timed-out result.
 * @internal
 */
function buildTimedOutResult(startTime: number): ComputationTimedOutResult {
  return {
    status: "timed-out",
    elapsedMs: Date.now() - startTime,
  };
}

/* =============================================================================
 * WEBSOCKET-BASED MONITOR
 * ============================================================================= */

/**
 * Creates a {@link ComputationMonitor} that uses WebSocket account change
 * subscriptions for real-time detection of computation finalization or pruning.
 *
 * @remarks
 * **Two-phase design:** {@link ComputationMonitor.prepareMonitor | prepareMonitor}
 * establishes the WebSocket subscription immediately so it is active before the
 * `queue_computation` transaction is sent. This eliminates the race condition
 * where a fast MPC callback could land between transaction confirmation and
 * subscription establishment.
 *
 * **Detection strategy:** Subscribes to `accountNotifications` for the
 * computation account. The first notification (from the `queue_computation`
 * transaction itself) is consumed silently to capture the queued slot. Subsequent
 * notifications are checked for `Finalized` status. Periodic slot checks detect
 * pruning when the slot window is exceeded.
 *
 * @param config - HTTP RPC URL and WebSocket URL.
 * @param deps - Optional dependency overrides for testing.
 * @returns A {@link ComputationMonitor} instance.
 *
 * @example
 * ```typescript
 * const monitor = getWebsocketComputationMonitor({
 *   rpcUrl: "https://api.mainnet-beta.solana.com",
 *   rpcSubscriptionsUrl: "wss://api.mainnet-beta.solana.com",
 * });
 *
 * // Phase 1: establish subscription
 * const prepared = await monitor.prepareMonitor(computationAddress);
 *
 * // Phase 2: send queue_computation transaction
 * await forwarder.forwardSequentially([signedTx]);
 *
 * // Phase 3: await result (first WS notification from queue tx is ignored)
 * const result = await prepared.awaitComputation();
 * switch (result.status) {
 *   case "finalized":
 *     console.log(`Done in ${result.elapsedMs}ms`);
 *     break;
 *   case "pruned":
 *     console.log(`Pruned after ${result.currentSlot - result.queuedSlot} slots`);
 *     break;
 *   case "timed-out":
 *     console.log(`Timed out after ${result.elapsedMs}ms`);
 *     break;
 * }
 * ```
 *
 * @see {@link getPollingComputationMonitor} for the polling alternative
 * @since 3.0.0
 * @public
 */
export function getWebsocketComputationMonitor(
  config: WebsocketBasedComputationMonitorConfig,
  deps?: WebsocketBasedComputationMonitorDeps,
): ComputationMonitor {
  const { rpcUrl, rpcSubscriptionsUrl } = config;
  const {
    createRpc = defaultCreateSolanaRpc,
    createRpcSubscriptions = defaultCreateSolanaRpcSubscriptions,
  } = deps ?? {};

  const rpc = createRpc(rpcUrl);
  const rpcSubscriptions = createRpcSubscriptions(rpcSubscriptionsUrl);

  async function prepareMonitor(
    computationAddress: Address,
    options?: ComputationMonitorOptions,
  ): Promise<PreparedComputationMonitor> {
    const {
      maxSlotWindow = DEFAULT_MAX_SLOT_WINDOW,
      safetyTimeoutMs = DEFAULT_SAFETY_TIMEOUT_MS,
      retrieveCallbackSignature: shouldRetrieveSignature = false,
      onProgress,
      commitment = "confirmed",
      signal: externalSignal,
    } = options ?? {};

    // ── Establish WebSocket subscription immediately ──
    const abortController = new AbortController();
    let cleaned = false;

    function cleanup(): void {
      if (cleaned) return;
      cleaned = true;
      abortController.abort();
    }

    let notifications: AsyncIterable<{
      value: { data: [string, "base64"]; executable: boolean; lamports: Lamports; owner: Address };
    }>;
    try {
      notifications = await rpcSubscriptions
        .accountNotifications(computationAddress, { encoding: "base64", commitment })
        .subscribe({ abortSignal: abortController.signal });
    } catch (error) {
      cleanup();
      throw new ComputationMonitorError(
        "subscription",
        "Failed to establish WebSocket subscription",
        error instanceof Error ? error : undefined,
      );
    }

    async function awaitComputation(): Promise<
      ComputationMonitorResult | ComputationMonitorResultWithSignature
    > {
      const startTime = Date.now();
      let queuedSlot: bigint | null = null;
      let receivedFirstNotification = false;

      checkAborted(externalSignal);

      const safetyTimeoutId = setTimeout(() => abortController.abort(), safetyTimeoutMs);

      const onExternalAbort = (): void => abortController.abort();
      externalSignal?.addEventListener("abort", onExternalAbort, { once: true });

      // Periodic slot check interval (started after first decode captures queuedSlot)
      let slotCheckIntervalId: ReturnType<typeof setInterval> | null = null;
      let pruneDetected: ComputationPrunedResult | null = null;

      try {
        for await (const notification of notifications) {
          try {
            const encodedAccount = notificationValueToEncodedAccount(
              computationAddress,
              notification.value,
            );
            const decoded = decodeComputationAccount(encodedAccount);

            // First notification is from the queue_computation tx itself — capture
            // the queued slot and start the slot check timer, but otherwise ignore it.
            if (!receivedFirstNotification) {
              receivedFirstNotification = true;
              queuedSlot = decoded.data.slot;

              // Start periodic slot check now that we know the queued slot
              const capturedQueuedSlot = queuedSlot;
              slotCheckIntervalId = setInterval(async () => {
                try {
                  const currentSlot = await fetchCurrentSlot(rpc, commitment);
                  if (isSlotWindowExceeded(capturedQueuedSlot, currentSlot, maxSlotWindow)) {
                    pruneDetected = buildPrunedResult(
                      startTime,
                      capturedQueuedSlot,
                      currentSlot,
                      onProgress,
                    );
                    abortController.abort();
                  }
                } catch {
                  // Non-fatal: slot check failed, will retry next interval
                }
              }, 5_000);

              // If already finalized on first notification (unlikely but possible
              // if the callback landed in the same slot), still handle it.
              if (decoded.data.status === ComputationStatus.Finalized) {
                return buildFinalizedResult(
                  rpc,
                  computationAddress,
                  startTime,
                  queuedSlot,
                  shouldRetrieveSignature,
                  onProgress,
                );
              }
              continue;
            }

            // Subsequent notifications — check for finalization
            if (decoded.data.status === ComputationStatus.Finalized) {
              return buildFinalizedResult(
                rpc,
                computationAddress,
                startTime,
                queuedSlot!,
                shouldRetrieveSignature,
                onProgress,
              );
            }
          } catch {
            // Decode errors are non-fatal
            continue;
          }
        }

        // Stream ended — return pruned if detected, otherwise timed out
        if (pruneDetected) {
          return pruneDetected;
        }
        return buildTimedOutResult(startTime);
      } catch (error) {
        if (error instanceof ComputationMonitorError) {
          throw error;
        }
        if (pruneDetected) {
          return pruneDetected;
        }
        // Abort (safety timeout or external signal) → timed out
        if (abortController.signal.aborted) {
          return buildTimedOutResult(startTime);
        }
        throw new ComputationMonitorError(
          "subscription",
          "WebSocket subscription failed",
          error instanceof Error ? error : undefined,
        );
      } finally {
        clearTimeout(safetyTimeoutId);
        if (slotCheckIntervalId !== null) {
          clearInterval(slotCheckIntervalId);
        }
        externalSignal?.removeEventListener("abort", onExternalAbort);
        cleanup();
      }
    }

    return { awaitComputation, cleanup };
  }

  return { prepareMonitor };
}

/* =============================================================================
 * POLLING-BASED MONITOR
 * ============================================================================= */

/**
 * Creates a {@link ComputationMonitor} that uses periodic HTTP account fetching
 * for detection of computation finalization or pruning.
 *
 * @remarks
 * Each poll iteration fetches the `ComputationAccount` and the current slot
 * in parallel. If the account is finalized, the monitor resolves. If the slot
 * window is exceeded, the monitor resolves with a pruned result. If the
 * wall-clock safety timeout fires, a `"timed-out"` result is returned.
 *
 * **Transient error handling** — RPC fetch errors during polling are silently
 * swallowed and the poll loop continues.
 *
 * @param config - HTTP RPC endpoint URL.
 * @param deps - Optional dependency overrides for testing.
 * @returns A {@link ComputationMonitor} instance.
 *
 * @throws {ComputationMonitorError} Stage `"signature-retrieval"` if lookup fails.
 *
 * @example
 * ```typescript
 * const monitor = getPollingComputationMonitor({
 *   rpcUrl: "https://api.mainnet-beta.solana.com",
 * });
 *
 * const prepared = await monitor.prepareMonitor(computationAddress, {
 *   maxSlotWindow: 250,
 *   pollingIntervalMs: 3_000,
 *   retrieveCallbackSignature: true,
 * });
 *
 * // ... send queue_computation transaction ...
 *
 * const result = await prepared.awaitComputation();
 * if (result.status === "finalized") {
 *   console.log(`Callback: ${result.callbackSignature}`);
 * }
 * ```
 *
 * @see {@link getWebsocketComputationMonitor} for the WebSocket alternative
 * @since 3.0.0
 * @public
 */
export function getPollingComputationMonitor(
  config: PollingBasedComputationMonitorConfig,
  deps?: PollingBasedComputationMonitorDeps,
): ComputationMonitor {
  const { rpcUrl } = config;
  const { createRpc = defaultCreateSolanaRpc } = deps ?? {};
  const rpc = createRpc(rpcUrl);

  async function prepareMonitor(
    computationAddress: Address,
    options?: PollingComputationMonitorOptions,
  ): Promise<PreparedComputationMonitor> {
    const {
      maxSlotWindow = DEFAULT_MAX_SLOT_WINDOW,
      safetyTimeoutMs = DEFAULT_SAFETY_TIMEOUT_MS,
      pollingIntervalMs = DEFAULT_POLLING_INTERVAL_MS,
      retrieveCallbackSignature: shouldRetrieveSignature = false,
      onProgress,
      commitment = "confirmed",
      signal: externalSignal,
    } = options ?? {};

    let aborted = false;

    function cleanup(): void {
      aborted = true;
    }

    async function awaitComputation(): Promise<
      ComputationMonitorResult | ComputationMonitorResultWithSignature
    > {
      const startTime = Date.now();
      let queuedSlot: bigint | null = null;
      let receivedFirstDecode = false;

      while (Date.now() - startTime < safetyTimeoutMs) {
        if (aborted) {
          return buildTimedOutResult(startTime);
        }
        checkAborted(externalSignal);

        try {
          // Fetch account and current slot in parallel
          const [maybeAccount, currentSlot] = await Promise.all([
            fetchEncodedAccount(rpc, computationAddress, { commitment }),
            fetchCurrentSlot(rpc, commitment),
          ]);

          if (!maybeAccount.exists) {
            await sleep(pollingIntervalMs);
            continue;
          }

          const decoded = decodeComputationAccount(maybeAccount);

          // Capture queued slot on first successful decode
          if (queuedSlot === null) {
            queuedSlot = decoded.data.slot;
          }

          // First decode is from the queue_computation tx — ignore it
          if (!receivedFirstDecode) {
            receivedFirstDecode = true;

            // If already finalized on first decode (unlikely), still handle it
            if (decoded.data.status === ComputationStatus.Finalized) {
              return buildFinalizedResult(
                rpc,
                computationAddress,
                startTime,
                queuedSlot,
                shouldRetrieveSignature,
                onProgress,
              );
            }

            await sleep(pollingIntervalMs);
            continue;
          }

          // Check finalization
          if (decoded.data.status === ComputationStatus.Finalized) {
            return buildFinalizedResult(
              rpc,
              computationAddress,
              startTime,
              queuedSlot,
              shouldRetrieveSignature,
              onProgress,
            );
          }

          // Check pruning
          if (isSlotWindowExceeded(queuedSlot, currentSlot, maxSlotWindow)) {
            return buildPrunedResult(startTime, queuedSlot, currentSlot, onProgress);
          }
        } catch (error) {
          if (error instanceof ComputationMonitorError) {
            throw error;
          }
          // Transient RPC errors: swallow and retry on next poll
        }

        await sleep(pollingIntervalMs);
      }

      return buildTimedOutResult(startTime);
    }

    return { awaitComputation, cleanup };
  }

  return { prepareMonitor };
}
