/**
 * Shared Transaction Execution Utility
 *
 * Provides a factory for creating a reusable transaction executor that handles
 * the common build → sign → forward → optionally-monitor flow shared across
 * all Umbra service functions that queue Arcium MPC computations.
 *
 * @remarks
 * Every confidential service (deposit, withdrawal, UTXO creation, compliance,
 * conversion, registration) follows the same high-level pattern:
 *
 * 1. Fetch a recent blockhash
 * 2. Build a v0 transaction message with fee payer, instructions, and optional ALT
 * 3. Sign the transaction
 * 4. Forward the signed transaction via `TransactionForwarder`
 * 5. Optionally await the Arcium MPC callback via `ComputationMonitor`
 *
 * Steps 1–3 vary per service (different signing strategies, error classes,
 * compute-unit limits). Steps 4–5 are identical everywhere and are extracted
 * into this shared utility.
 *
 * @module umbra/services/execute-computation-transaction
 */

import type { Address, Commitment, Instruction } from "@solana/kit";
import {
  pipe,
  createTransactionMessage,
  setTransactionMessageFeePayer,
  setTransactionMessageLifetimeUsingBlockhash,
  appendTransactionMessageInstructions,
  compressTransactionMessageUsingAddressLookupTables,
  partiallySignTransactionMessageWithSigners,
  getSignatureFromTransaction,
  createNoopSigner,
} from "@solana/kit";

import { getClaimComputationRentInstruction } from "@umbra-privacy/arcium-codama";

import type { AltEntry } from "../../constants/networks";
import type { GetLatestBlockhash, TransactionForwarder } from "../../solana/interfaces";
import type { TransactionSignature, SignedTransaction } from "../../solana/types";
import { buildAltAddressesRecord } from "../../solana/alt-utils";
import type {
  ComputationMonitor,
  ComputationMonitorOptions,
  ComputationMonitorResult,
  ComputationMonitorResultWithSignature,
  PreparedComputationMonitor,
} from "../../arcium/computation-monitor";
import type { IUmbraSigner, SignableTransaction, TransactionCallbacks } from "../interfaces";

/* =============================================================================
 * TYPES
 * ============================================================================= */

/**
 * Configuration for the transaction executor factory.
 *
 * These are the long-lived dependencies that remain constant across
 * multiple invocations of the executor within a single service instance.
 */
export interface TransactionExecutorConfig {
  /** The wallet signer providing fee-payer address and signing capability. */
  readonly signer: IUmbraSigner;

  /** Provider for fetching the latest blockhash. */
  readonly getLatestBlockhash: GetLatestBlockhash;

  /** Forwarder for submitting signed transactions to the network. */
  readonly transactionForwarder: TransactionForwarder;

  /** Optional computation monitor for awaiting MPC callbacks. */
  readonly computationMonitor?: ComputationMonitor;
}

/**
 * Options for a single transaction execution.
 */
export interface ExecuteTransactionOptions {
  /** The main instruction to execute. */
  readonly instruction: Instruction;

  /** Optional instructions to prepend before the main instruction. */
  readonly preInstructions?: readonly Instruction[];

  /** Optional ALT entry for transaction compression. */
  readonly altEntry?: AltEntry;

  /** Optional lifecycle callbacks invoked around the transaction. */
  readonly callbacks?: TransactionCallbacks;

  /**
   * Commitment level for the `getLatestBlockhash` call used to set
   * the transaction's lifetime constraint.
   * @defaultValue `"confirmed"`
   */
  readonly blockhashCommitment?: Commitment;
}

/**
 * Options for awaiting the MPC computation callback after transaction submission.
 *
 * When provided to the executor, it will monitor the `ComputationAccount` for
 * finalization after the queue transaction is confirmed.
 */
export interface AwaitCallbackOptions {
  /** The on-chain address of the ComputationAccount PDA to monitor. */
  readonly computationAccountAddress: Address;

  /**
   * If `true`, retrieve the callback transaction signature after finalization.
   *
   * @defaultValue `false`
   */
  readonly retrieveCallbackSignature?: boolean;

  /**
   * Maximum slot window before the computation is considered pruned.
   * @see {@link ComputationMonitorOptions.maxSlotWindow}
   */
  readonly maxSlotWindow?: number;

  /**
   * Wall-clock safety timeout in milliseconds.
   * @see {@link ComputationMonitorOptions.safetyTimeoutMs}
   */
  readonly safetyTimeoutMs?: number;

  /** Progress callback forwarded to the computation monitor. */
  readonly onProgress?: ComputationMonitorOptions["onProgress"];

  /**
   * If `true` (the default), send a `claimComputationRent` transaction after
   * the callback finalizes to reclaim the SOL rent from the closed computation
   * account. Set to `false` to skip rent reclamation.
   *
   * Only takes effect when callback monitoring is active. Requires
   * `computationOffset` and `clusterOffset` to be set (filled automatically
   * by each service — not part of the user-facing `AwaitComputationFinalizationConfig`).
   *
   * @defaultValue `true`
   */
  readonly reclaimComputationRent?: boolean;

  /**
   * The computation offset used to derive the computation account PDA.
   * Filled automatically by each service. Not exposed in `AwaitComputationFinalizationConfig`.
   * @internal
   */
  readonly computationOffset?: bigint;

  /**
   * The cluster offset of the Arcium cluster that processed the computation.
   * Filled automatically by each service. Not exposed in `AwaitComputationFinalizationConfig`.
   * @internal
   */
  readonly clusterOffset?: number;

  /**
   * Commitment level for the computation monitor's account polling and
   * slot tracking during MPC callback detection.
   * @defaultValue `"confirmed"`
   */
  readonly computationMonitorCommitment?: Commitment;

  /**
   * Commitment level for the `getLatestBlockhash` call used by the
   * rent reclaim transaction (if `reclaimComputationRent` is enabled).
   * @defaultValue `"confirmed"`
   */
  readonly rentReclaimBlockhashCommitment?: Commitment;
}

/**
 * Result of executing a transaction without awaiting a callback.
 */
export interface TransactionExecutionResult {
  /** The confirmed transaction signature (queue transaction). */
  readonly signature: TransactionSignature;

  /** The fully signed transaction that was submitted. */
  readonly signedTransaction: SignedTransaction;
}

/**
 * Result of executing a transaction with callback awaiting.
 */
export interface TransactionExecutionResultWithCallback extends TransactionExecutionResult {
  /** The computation monitor result after finalization. */
  readonly callbackResult: ComputationMonitorResult | ComputationMonitorResultWithSignature;

  /**
   * The signature of the `claimComputationRent` transaction, if
   * `reclaimComputationRent` was enabled and the claim succeeded.
   */
  readonly rentClaimSignature?: TransactionSignature;

  /**
   * Error message from the `claimComputationRent` transaction, if the claim
   * was attempted but failed. The callback result is still valid in this case.
   */
  readonly rentClaimError?: string;
}

/**
 * Extracts all transaction signatures from an execution result.
 *
 * Returns the queue transaction signature, and if a callback was awaited
 * and the callback signature was retrieved, appends it as well.
 */
export function extractSignatures(
  result: TransactionExecutionResult | TransactionExecutionResultWithCallback,
): TransactionSignature[] {
  const signatures: TransactionSignature[] = [result.signature];

  if (
    "callbackResult" in result &&
    result.callbackResult.status === "finalized" &&
    result.callbackResult.callbackSignature !== undefined
  ) {
    signatures.push(result.callbackResult.callbackSignature);
  }

  return signatures;
}

/* =============================================================================
 * BUILD TRANSACTION MESSAGE
 * ============================================================================= */

/**
 * Builds a versioned transaction message from instructions, fee payer, blockhash,
 * and optional address lookup table.
 *
 * @param signer - The wallet signer (provides fee payer address)
 * @param latestBlockhash - The latest blockhash for transaction lifetime
 * @param instructions - The ordered list of instructions to include
 * @param altEntry - Optional ALT entry for transaction compression
 * @returns The built transaction message, optionally compressed with ALT
 *
 * @internal
 */

export function buildTransactionMessage(
  signer: IUmbraSigner,
  latestBlockhash: Awaited<ReturnType<GetLatestBlockhash>>,
  instructions: readonly Instruction[],
  altEntry?: AltEntry,
) {
  const baseTransactionMessage = pipe(
    createTransactionMessage({ version: 0 }),
    (m) => setTransactionMessageFeePayer(signer.address, m),
    (m) => setTransactionMessageLifetimeUsingBlockhash(latestBlockhash, m),
    (m) => appendTransactionMessageInstructions([...instructions], m),
  );

  if (altEntry === undefined) {
    return baseTransactionMessage;
  }

  return compressTransactionMessageUsingAddressLookupTables(
    baseTransactionMessage,
    buildAltAddressesRecord(altEntry),
  );
}

/* =============================================================================
 * SIGN TRANSACTION
 * ============================================================================= */

/**
 * Signs a transaction message using the partial-sign-then-wallet-sign strategy.
 *
 * This is the default signing approach used by most services. It first
 * partially signs with any `TransactionSigner`s embedded in the message
 * (e.g., NoopSigners), then signs with the wallet signer.
 *
 * @param signer - The wallet signer
 * @param transactionMessage - The transaction message to sign
 * @returns The fully signed transaction
 *
 * @internal
 */
export async function signTransactionMessage(
  signer: IUmbraSigner,
  transactionMessage: Parameters<typeof partiallySignTransactionMessageWithSigners>[0],
): Promise<SignedTransaction> {
  const partiallySignedTransaction =
    await partiallySignTransactionMessageWithSigners(transactionMessage);
  return await signer.signTransaction(partiallySignedTransaction as SignableTransaction);
}

/* =============================================================================
 * FORWARD AND MONITOR
 * ============================================================================= */

/**
 * Forwards a signed transaction and optionally monitors the computation for finalization.
 *
 * This is the shared core extracted from all service `executeTransaction` closures.
 * It handles:
 * 1. Preparing the computation monitor (establishing WebSocket subscription)
 * 2. Invoking the optional `pre` callback with the signed transaction
 * 3. Submitting the transaction via `TransactionForwarder.forwardSequentially`
 * 4. Invoking the optional `post` callback with the transaction and signature
 * 5. Awaiting the MPC computation callback via the prepared monitor
 * 6. Closing the computation account regardless of outcome
 *
 * The monitor is prepared **before** the transaction is sent so the subscription
 * is active when the `queue_computation` transaction lands. The first account
 * notification (from the queue transaction itself) is consumed silently.
 *
 * @param config - The long-lived executor configuration
 * @param signedTransaction - The signed transaction to forward
 * @param callbacks - Optional pre/post lifecycle callbacks
 * @param awaitCallback - Optional callback-monitoring options
 * @returns The transaction result, optionally extended with callback result
 *
 * @internal
 */
export async function forwardAndMonitor(
  config: TransactionExecutorConfig,
  signedTransaction: SignedTransaction,
  callbacks?: TransactionCallbacks,
  awaitCallback?: AwaitCallbackOptions,
): Promise<TransactionExecutionResult | TransactionExecutionResultWithCallback> {
  const { transactionForwarder, computationMonitor } = config;

  // Extract signature from the signed transaction
  const txSignature = getSignatureFromTransaction(
    signedTransaction,
  ) as string as TransactionSignature;

  // ── Phase 1: Prepare the computation monitor BEFORE sending the tx ──
  let prepared: PreparedComputationMonitor | undefined;

  if (awaitCallback !== undefined) {
    if (computationMonitor === undefined) {
      throw new Error(
        "awaitCallback was provided but no computationMonitor is configured on the client. " +
          "Pass a computationMonitor when creating the Umbra client, or omit awaitCallback to use fire-and-forget mode.",
      );
    }

    const baseMonitorOptions: ComputationMonitorOptions = {
      maxSlotWindow: awaitCallback.maxSlotWindow,
      safetyTimeoutMs: awaitCallback.safetyTimeoutMs,
      onProgress: awaitCallback.onProgress,
      commitment: awaitCallback.computationMonitorCommitment ?? "confirmed",
      retrieveCallbackSignature: awaitCallback.retrieveCallbackSignature ?? false,
    };

    prepared = await computationMonitor.prepareMonitor(
      awaitCallback.computationAccountAddress,
      baseMonitorOptions,
    );
  }

  try {
    // ── Phase 2: Send the queue_computation transaction ──

    // Invoke pre-send callback
    if (callbacks?.pre !== undefined) {
      await callbacks.pre(signedTransaction);
    }

    // Forward the transaction
    await transactionForwarder.forwardSequentially([signedTransaction]);

    // Invoke post-send callback
    if (callbacks?.post !== undefined) {
      await callbacks.post(signedTransaction, txSignature);
    }

    // If no callback monitoring requested, return immediately
    if (prepared === undefined || awaitCallback === undefined) {
      return { signature: txSignature, signedTransaction };
    }

    // ── Phase 3: Await computation result ──
    const callbackResult = await prepared.awaitComputation();

    // ── Phase 4: Close computation account regardless of outcome ──
    let rentClaimSignature: TransactionSignature | undefined;
    let rentClaimError: string | undefined;

    if (awaitCallback.reclaimComputationRent !== false) {
      if (
        awaitCallback.computationOffset === undefined ||
        awaitCallback.clusterOffset === undefined
      ) {
        rentClaimError =
          "Rent reclaim skipped: computationOffset or clusterOffset was not provided by the service";
      } else {
        try {
          const noopSigner = createNoopSigner(config.signer.address);
          const rentClaimIx = getClaimComputationRentInstruction({
            signer: noopSigner,
            comp: awaitCallback.computationAccountAddress,
            compOffset: awaitCallback.computationOffset,
            clusterOffset: awaitCallback.clusterOffset,
          });
          const rentClaimBlockhash = await config.getLatestBlockhash({
            commitment: awaitCallback.rentReclaimBlockhashCommitment ?? "confirmed",
          });
          const rentClaimTxMsg = buildTransactionMessage(config.signer, rentClaimBlockhash, [
            rentClaimIx,
          ]);
          const rentClaimTx = await signTransactionMessage(config.signer, rentClaimTxMsg);
          rentClaimSignature = await config.transactionForwarder.fireAndForget(rentClaimTx);
        } catch (error) {
          rentClaimError = error instanceof Error ? error.message : String(error);
        }
      }
    }

    return {
      signature: txSignature,
      signedTransaction,
      callbackResult,
      rentClaimSignature,
      rentClaimError,
    };
  } finally {
    // Ensure the subscription is cleaned up even if the tx forward fails
    prepared?.cleanup();
  }
}

/* =============================================================================
 * FULL EXECUTOR
 * ============================================================================= */

/**
 * Executes a full build → sign → forward → optionally-monitor pipeline.
 *
 * This is a convenience function that combines `buildTransactionMessage`,
 * `signTransactionMessage`, and `forwardAndMonitor` into a single call.
 * It uses the default partial-sign-then-wallet-sign strategy.
 *
 * Services that need a different signing strategy (e.g., `compileTransaction`)
 * should use `buildTransactionMessage` and `forwardAndMonitor` separately.
 *
 * @param config - The long-lived executor configuration
 * @param options - Per-invocation transaction options. Includes `blockhashCommitment`
 *   (default `"confirmed"`) for the blockhash fetch.
 * @param awaitCallback - Optional callback-monitoring options. Includes
 *   `computationMonitorCommitment` (default `"confirmed"`) for MPC callback detection
 *   and `rentReclaimBlockhashCommitment` (default `"confirmed"`) for the rent reclaim tx.
 * @returns The transaction result, optionally extended with callback result
 */
export async function executeComputationTransaction(
  config: TransactionExecutorConfig,
  options: ExecuteTransactionOptions,
  awaitCallback?: AwaitCallbackOptions,
): Promise<TransactionExecutionResult | TransactionExecutionResultWithCallback> {
  const { signer, getLatestBlockhash } = config;
  const { instruction, preInstructions, altEntry, callbacks, blockhashCommitment } = options;

  // Fetch latest blockhash
  const latestBlockhash = await getLatestBlockhash({
    commitment: blockhashCommitment ?? "confirmed",
  });

  // Build transaction message
  const allInstructions =
    preInstructions === undefined ? [instruction] : [...preInstructions, instruction];

  const transactionMessage = buildTransactionMessage(
    signer,
    latestBlockhash,
    allInstructions,
    altEntry,
  );

  // Sign transaction
  const signedTransaction = await signTransactionMessage(signer, transactionMessage);

  // Forward and optionally monitor
  return forwardAndMonitor(config, signedTransaction, callbacks, awaitCallback);
}
