/**
 * Umbra Client Implementation.
 *
 * @remarks
 * This module is the top-level entry point for the Umbra SDK. It provides:
 *
 * - {@link getUmbraClient} — factory function that constructs an
 *   {@link IUmbraClient} from a wallet signer, performing the one-time master
 *   seed derivation step.
 * - {@link getUserRegistrationFunction} — factory that creates the idempotent
 *   user registration function, which handles all on-chain registration steps
 *   (account init, X25519 key registration, anonymous usage commitment).
 *
 * **Architecture overview:**
 * `UmbraClient` is a plain configuration object (not a class) that holds all
 * shared state and injected dependencies for a session. Service-specific factory
 * functions (`getUserRegistrationFunction`, `getDepositFunction`, etc.) accept
 * an `IUmbraClient` and return callable functions, following the functional
 * dependency-injection pattern used throughout the SDK.
 *
 * **Initialization flow:**
 * ```
 * wallet signer
 *   └─► getUmbraClient({ signer, network, rpcUrl, ... })
 *         └─► [one-time signing prompt to derive master seed]
 *         └─► IUmbraClient (config object with all dependencies wired up)
 *               ├─► getUserRegistrationFunction({ client })
 *               ├─► getDepositFunction({ client })
 *               ├─► getClaimFunction({ client })
 *               └─► ... other service factories
 * ```
 *
 * **Dependency injection:**
 * Every factory accepts an optional `deps` argument for overriding individual
 * dependencies. This enables testing without a live Solana RPC node and without
 * a real wallet signer.
 *
 * @since 2.0.0
 * @module implementation/umbra/client
 * @packageDocumentation
 */

import type {
  MasterSeed,
  X25519PrivateKey,
  Bn254FieldElement,
  U512,
  MasterSeedLoaderFunction,
  MasterSeedStorerFunction,
  MasterSeedGeneratorFunction,
  MasterViewingKey,
  PoseidonKey,
  YearlyViewingKey,
  MonthlyViewingKey,
  DailyViewingKey,
  MintViewingKey,
  Curve25519FieldElement,
} from "../types";
import type {
  Network,
  ProtocolVersionSpecifierFunction,
  AlgorithmVersionSpecifierFunction,
  SchemeVersionSpecifierFunction,
} from "../constants/versions";
import {
  getDefaultProtocolVersion,
  getDefaultAlgorithmVersion,
  getDefaultSchemeVersion,
  getNetworkSpecifier,
} from "../constants/versions";
import { getNetworkConfig } from "../constants/networks";
import {
  getDefaultMasterSeedStorage,
  getDefaultMasterSeedGenerator,
  getDefaultKeyLoader,
  getDefaultKeyStorer,
} from "../common/storage";
// Indexer factories are lazy-loaded to avoid pulling in protobufjs (and its
// Node.js crypto polyfill chain) when the indexer is not used.
// import { getBatchMerkleProofFetcher, getMerkleProofFetcher, getUtxoDataFetcher } from "./indexer";
import type { IUmbraClient } from "./interfaces";
import type { IUmbraSigner } from "./interfaces";
import type {
  GetLatestBlockhash,
  AccountInfoProviderFunction as AccountInfoProviderFunction,
  TransactionForwarder,
  GetEpochInfo,
} from "../solana/interfaces";
import { getRpcAccountInfoProvider } from "../solana/account-info-provider";
import { getRpcBlockhashProvider } from "../solana/blockhash-provider";
import { getWebsocketTransactionForwarder } from "../solana/transaction-forwarder";
import { getRpcEpochInfoProvider } from "../solana/epoch-info-provider";
import { getWebsocketComputationMonitor } from "../arcium/computation-monitor";
import type { ComputationMonitor } from "../arcium/computation-monitor";

/* =============================================================================
 * TYPES
 * ============================================================================= */

/**
 * Arguments for creating an Umbra client from a wallet signer.
 *
 * @remarks
 * These arguments configure all infrastructure dependencies for a session.
 * Required fields are `signer`, `network`, `rpcUrl`, and `rpcSubscriptionsUrl`.
 * Everything else has a sensible default.
 *
 * The client is immutable after construction. To use a different signer or
 * network, create a new client.
 *
 * @public
 */
export interface GetUmbraClientArgs {
  /**
   * The signer to use for deriving the master seed and signing transactions.
   *
   * @remarks
   * The signer's `signMessage` method is called exactly once during the first
   * invocation of `getMasterSeed()`. The resulting Ed25519 signature is hashed
   * with Keccak-512 to produce the 64-byte master seed, which is then cached
   * in memory for the lifetime of the client. No further signing prompts are
   * issued for key derivation.
   *
   * The signer's `signTransaction` method is called once per on-chain operation
   * to add the user's fee-payer signature.
   *
   * Implementations must satisfy the {@link IUmbraSigner} interface.
   */
  readonly signer: IUmbraSigner;

  /**
   * Network environment to connect to.
   *
   * @remarks
   * Controls which program ID, Arcium cluster addresses, and Address Lookup
   * Tables are used. The network config is resolved via `getNetworkConfig(network)`
   * and throws if the network is not populated.
   *
   * Accepted values: `"mainnet"`, `"devnet"`, `"localnet"`.
   */
  readonly network: Network;

  /**
   * The Solana JSON-RPC HTTP endpoint URL.
   *
   * @remarks
   * Used to construct the default `accountInfoProvider` and `blockhashProvider`
   * if those dependencies are not overridden in `deps`. Accepts any standard
   * Solana RPC URL including cluster.quiknode.pro, api.mainnet-beta.solana.com,
   * or a local validator.
   */
  readonly rpcUrl: string;

  /**
   * The Solana WebSocket RPC endpoint URL for subscription-based confirmations.
   *
   * @remarks
   * Used to construct the default `transactionForwarder` if not overridden in
   * `deps`. The WebSocket connection enables efficient transaction confirmation
   * via `signatureSubscribe` rather than polling.
   *
   * Typically the same host as `rpcUrl` but with `wss://` scheme.
   */
  readonly rpcSubscriptionsUrl: string;

  /**
   * Optional indexer API endpoint for UTXO discovery and Merkle proof fetching.
   *
   * @remarks
   * When provided, the client's `fetchMerkleProof` and `fetchUtxoData` fields
   * are populated with functions that query the indexer read service. If omitted
   * or empty, those fields are absent from the returned client and UTXO scanning
   * operations will need alternative data sources.
   *
   * The indexer is UNTRUSTED — see indexer.ts for the verification requirements.
   */
  readonly indexerApiEndpoint?: string;

  /**
   * Optional custom protocol/algorithm/scheme version specifiers.
   *
   * @remarks
   * Override individual version specifier functions to opt into non-default
   * protocol, algorithm, or encryption scheme versions. This is typically only
   * needed during protocol upgrades or for testing against a specific version.
   *
   * If not provided, the SDK uses the current default versions returned by
   * `getDefaultProtocolVersion`, `getDefaultAlgorithmVersion`, and
   * `getDefaultSchemeVersion`.
   *
   * @defaultValue Uses default version specifiers for all three fields
   */
  readonly versions?: {
    readonly protocol?: ProtocolVersionSpecifierFunction;
    readonly algorithm?: AlgorithmVersionSpecifierFunction;
    readonly scheme?: SchemeVersionSpecifierFunction;
  };

  /**
   * Optional U512 offsets for key derivation.
   *
   * @remarks
   * Each key in the Umbra key hierarchy is derived by hashing `masterSeed ‖ index ‖ offset`.
   * Offsets allow key rotation: incrementing an offset produces an entirely different
   * derived key from the same master seed, without requiring a new wallet signature.
   *
   * In normal usage all offsets are zero. Key rotation (e.g. after a suspected
   * compromise) is performed by incrementing the relevant offset.
   *
   * @defaultValue `0n` for all offsets
   */
  readonly offsets?: {
    readonly masterViewingKey?: U512;
    readonly poseidonPrivateKey?: U512;
    readonly x25519UserAccountPrivateKey?: U512;
    readonly x25519MasterViewingKeyEncryptingPrivateKey?: U512;
    readonly mintX25519PrivateKey?: U512;
    readonly rescueCommitmentBlindingFactor?: U512;
    readonly randomCommitmentFactor?: U512;
  };

  /**
   * Whether to defer the master seed signing prompt to first use.
   *
   * @remarks
   * When `false` (the default), the factory awaits master seed derivation
   * before resolving. The wallet signing prompt fires immediately during
   * construction so that by the time the returned `Promise` resolves, the
   * master seed is already cached and no further wallet prompts will occur
   * for key derivation.
   *
   * When `true`, `getUmbraClient` resolves immediately without prompting
   * the wallet. The signing prompt for master seed derivation fires lazily
   * on the first call to `client.masterSeed.getMasterSeed()`, which occurs
   * automatically the first time any service function needs a derived key.
   *
   * Use `true` when you want the client to be available instantly (e.g. at
   * wallet connect time) and defer the signing prompt to the first operation.
   *
   * @defaultValue `false`
   */
  readonly deferMasterSeedSignature?: boolean;
}

/**
 * Optional dependency overrides for {@link getUmbraClient}.
 *
 * @remarks
 * All fields are optional. When omitted, the factory constructs defaults from
 * the URLs in {@link GetUmbraClientArgs}. Providing overrides enables:
 * - **Unit testing** without a live RPC node or wallet
 * - **Custom persistence** of the master seed (e.g. hardware wallet, secure enclave)
 * - **Custom transport** for transactions (e.g. Jito bundles, priority fee manager)
 *
 * @public
 */
export interface GetUmbraClientDeps {
  /**
   * Override the account information provider.
   *
   * @remarks
   * The default is constructed from `rpcUrl` via `getRpcAccountInfoProvider`.
   * Provide a mock implementation to test registration flows without a live RPC.
   *
   * @defaultValue Constructed from `rpcUrl`
   */
  readonly accountInfoProvider?: AccountInfoProviderFunction;

  /**
   * Override the latest blockhash provider.
   *
   * @remarks
   * The default is constructed from `rpcUrl` via `getRpcBlockhashProvider`.
   * Override to inject a deterministic blockhash for snapshot tests.
   *
   * @defaultValue Constructed from `rpcUrl`
   */
  readonly blockhashProvider?: GetLatestBlockhash;

  /**
   * Override the transaction forwarder.
   *
   * @remarks
   * The default is a WebSocket-based forwarder constructed from `rpcUrl` and
   * `rpcSubscriptionsUrl` via `getWebsocketTransactionForwarder`.
   * Override to inject a mock forwarder or a custom broadcasting strategy
   * such as Jito MEV bundles.
   *
   * @defaultValue Constructed from `rpcUrl` and `rpcSubscriptionsUrl`
   */
  readonly transactionForwarder?: TransactionForwarder;

  /**
   * Override the epoch information provider.
   *
   * @remarks
   * The default is constructed from `rpcUrl` via `getRpcEpochInfoProvider`.
   * Used for Token-2022 transfer fee schedule selection.
   * Override to inject a mock implementation for testing.
   *
   * @defaultValue Constructed from `rpcUrl`
   */
  readonly epochInfoProvider?: GetEpochInfo;

  /**
   * Override the computation monitor.
   *
   * @remarks
   * The default is a WebSocket-based monitor constructed from `rpcUrl` and
   * `rpcSubscriptionsUrl` via `getWebsocketComputationMonitor`.
   * Override to inject a polling-based monitor or a mock for testing.
   *
   * Set to `undefined` (or omit) to use the default. The monitor is optional
   * on `IUmbraClient` — callers that don't need MPC callback monitoring
   * can simply not call `prepareMonitor`.
   *
   * @defaultValue Constructed from `rpcUrl` and `rpcSubscriptionsUrl`
   */
  readonly computationMonitor?: ComputationMonitor;

  /**
   * Override master seed storage functions.
   *
   * @remarks
   * The master seed is the root secret from which all Umbra keys are derived.
   * By default it is stored purely in memory (lost on page refresh or process exit).
   *
   * Override individual storage functions to persist the seed in secure storage
   * (e.g. encrypted localStorage, a hardware wallet, or a secure server-side session):
   * - `load` — called first; if it returns `{ exists: true, seed }`, signing is skipped
   * - `generate` — called if `load` returns `{ exists: false }`; should prompt the user to sign
   * - `store` — called after `generate` to persist the newly derived seed
   *
   * @privateRemarks
   * Security note: the master seed is a 64-byte secret equivalent in sensitivity to
   * a root private key. Store it with the same care as a wallet private key.
   */
  readonly masterSeedStorage?: {
    readonly load?: MasterSeedLoaderFunction;
    readonly store?: MasterSeedStorerFunction;
    readonly generate?: MasterSeedGeneratorFunction;
  };
}

/* =============================================================================
 * GET UMBRA CLIENT FROM SIGNER
 * ============================================================================= */

/**
 * Creates an Umbra client from a wallet signer.
 *
 * @remarks
 * This is the primary factory function for the Umbra SDK. It wires up all
 * infrastructure dependencies and returns an {@link IUmbraClient} that serves
 * as the shared context for all subsequent SDK operations.
 *
 * **By default (`deferMasterSeedSignature: false`), this function prompts the
 * user to sign the master seed derivation message at construction time.** The
 * returned `Promise` resolves only after the wallet has signed and the master
 * seed is cached. All subsequent `getMasterSeed()` calls return the cached value
 * without further wallet prompts for the lifetime of the client.
 *
 * Set `deferMasterSeedSignature: true` to defer signing to first use. Master
 * seed derivation is lazy — it only occurs on the first call to
 * `client.masterSeed.getMasterSeed()`, which fires automatically when the first
 * service function needs a derived key.
 *
 * **Master seed caching:**
 * After the user signs once and the seed is derived, it is cached by the default
 * in-memory storage. Subsequent calls to `getMasterSeed()` return the cached
 * value without any further signing prompts for the lifetime of the client.
 *
 * **Key derivation:**
 * All Umbra cryptographic keys (X25519, Poseidon, Master Viewing Key, etc.) are
 * derived deterministically from the master seed using HKDF or domain-separated
 * Keccak. The `offsets` argument enables key rotation without requiring a new
 * wallet signature.
 *
 * **Indexer integration:**
 * If `indexerApiEndpoint` is provided, the returned client includes `fetchMerkleProof`
 * and `fetchUtxoData` functions pre-configured for that endpoint. If omitted,
 * those fields are absent and UTXO discovery must be performed by other means.
 *
 * @param args - Configuration for the client session
 * @param args.signer - Wallet signer for message signing and transaction signing
 * @param args.network - Target network (`"mainnet"`, `"devnet"`, `"localnet"`)
 * @param args.rpcUrl - Solana JSON-RPC HTTP endpoint
 * @param args.rpcSubscriptionsUrl - Solana WebSocket RPC endpoint for confirmations
 * @param args.indexerApiEndpoint - Optional Umbra indexer endpoint for UTXO discovery
 * @param args.versions - Optional custom version specifiers
 * @param args.offsets - Optional U512 key derivation offsets (all default to `0n`)
 * @param args.deferMasterSeedSignature - `false` (default) signs eagerly during construction; `true` defers wallet signing to first use
 * @param deps - Optional dependency overrides for testing or customisation
 * @returns A `Promise<IUmbraClient>` that resolves with a fully configured client.
 *   Awaits master seed derivation when `deferMasterSeedSignature` is `false` (default);
 *   resolves immediately (no wallet prompt) when `true`.
 *
 * @throws {Error} If `network` is not a recognised network (from `getNetworkConfig`)
 *
 * @example
 * ```typescript
 * import { getUmbraClient } from '@umbra-privacy/sdk';
 *
 * // Eager mode (default): signing prompt fires during construction, seed cached before first operation
 * const client = await getUmbraClient({
 *   signer,
 *   network: 'mainnet',
 *   rpcUrl: 'https://api.mainnet-beta.solana.com',
 *   rpcSubscriptionsUrl: 'wss://api.mainnet-beta.solana.com',
 *   indexerApiEndpoint: 'https://indexer.umbra.finance',
 * });
 * // Master seed is already cached — no further wallet prompts for key derivation
 * ```
 *
 * @example
 * ```typescript
 * // Lazy mode: resolves immediately, signing prompt deferred to first use
 * const client = await getUmbraClient({
 *   signer,
 *   network: 'mainnet',
 *   rpcUrl: 'https://api.mainnet-beta.solana.com',
 *   rpcSubscriptionsUrl: 'wss://api.mainnet-beta.solana.com',
 *   deferMasterSeedSignature: true,
 * });
 * ```
 *
 * @example
 * ```typescript
 * // With custom key rotation offset
 * const client = await getUmbraClient({
 *   signer,
 *   network: 'devnet',
 *   rpcUrl: 'https://api.devnet.solana.com',
 *   rpcSubscriptionsUrl: 'wss://api.devnet.solana.com',
 *   offsets: {
 *     masterViewingKey: 1n as U512, // Rotate master viewing key
 *   },
 * });
 * ```
 *
 * @example
 * ```typescript
 * // Dependency injection for unit testing
 * const client = await getUmbraClient(
 *   { signer: mockSigner, network: 'localnet', rpcUrl: '...', rpcSubscriptionsUrl: '...' },
 *   {
 *     accountInfoProvider: mockAccountInfoProvider,
 *     transactionForwarder: mockForwarder,
 *     masterSeedStorage: { generate: async () => fixedTestSeed },
 *   }
 * );
 * ```
 *
 * @see {@link IUmbraClient}
 * @see {@link getUserRegistrationFunction}
 * @public
 */

/**
 * Placeholder generator that throws `"Not implemented yet"`.
 *
 * @remarks
 * Used as the `generate` function for key storage objects that do not yet
 * have a real generation path wired up. These slots exist in the client
 * for future use and will be populated as the SDK evolves.
 *
 * Calling this function always rejects with an `Error`. It is never called
 * unless a consumer explicitly requests key generation via the storage API
 * for an unimplemented key type.
 *
 * @returns A Promise that always rejects with `Error("Not implemented yet")`
 *
 * @internal
 */
 
const notImplementedGenerator = async (): Promise<never> => {
  throw new Error("Not implemented yet");
};

/**
 * @public
 */
export async function getUmbraClient(
  args: GetUmbraClientArgs,
  deps?: GetUmbraClientDeps,
): Promise<IUmbraClient> {
  // Destructure args with defaults
  const {
    signer,
    network,
    rpcUrl,
    rpcSubscriptionsUrl,
    indexerApiEndpoint,
    versions: customVersions,
    offsets: customOffsets,
    deferMasterSeedSignature = false,
  } = args;

  // Resolve network configuration (throws if network is unpopulated)
  const networkConfig = getNetworkConfig(network);

  // Set up version specifiers (custom or defaults)
  const versions = {
    protocol: customVersions?.protocol ?? getDefaultProtocolVersion,
    algorithm: customVersions?.algorithm ?? getDefaultAlgorithmVersion,
    scheme: customVersions?.scheme ?? getDefaultSchemeVersion,
    network: getNetworkSpecifier(network),
  };

  // Set up U512 offsets (custom or default 0n)
  const offsets = {
    masterViewingKey: customOffsets?.masterViewingKey ?? (0n as U512),
    poseidonPrivateKey: customOffsets?.poseidonPrivateKey ?? (0n as U512),
    x25519UserAccountPrivateKey: customOffsets?.x25519UserAccountPrivateKey ?? (0n as U512),
    x25519MasterViewingKeyEncryptingPrivateKey:
      customOffsets?.x25519MasterViewingKeyEncryptingPrivateKey ?? (0n as U512),
    mintX25519PrivateKey: customOffsets?.mintX25519PrivateKey ?? (0n as U512),
    rescueCommitmentBlindingFactor: customOffsets?.rescueCommitmentBlindingFactor ?? (0n as U512),
    randomCommitmentFactor: customOffsets?.randomCommitmentFactor ?? (0n as U512),
  };

  // Construct infrastructure dependencies (use overrides or construct from URLs)
  const accountInfoProvider =
    deps?.accountInfoProvider ?? getRpcAccountInfoProvider({ rpcUrl });

  const blockhashProvider = deps?.blockhashProvider ?? getRpcBlockhashProvider({ rpcUrl });

  const transactionForwarder =
    deps?.transactionForwarder ??
    getWebsocketTransactionForwarder({
      rpcUrl,
      rpcSubscriptionsUrl,
    });

  const epochInfoProvider = deps?.epochInfoProvider ?? getRpcEpochInfoProvider({ rpcUrl });

  const computationMonitor =
    deps?.computationMonitor ??
    getWebsocketComputationMonitor({
      rpcUrl,
      rpcSubscriptionsUrl,
    });

  // Construct indexer fetchers if endpoint provided.
  // The indexer module is loaded dynamically to avoid pulling in protobufjs
  // (and its Node.js Buffer/crypto polyfill chain) for apps that don't use
  // the indexer. This keeps the SDK browser-compatible without polyfills.
  let fetchMerkleProof: IUmbraClient["fetchMerkleProof"];
  let fetchBatchMerkleProof: IUmbraClient["fetchBatchMerkleProof"];
  let fetchUtxoData: IUmbraClient["fetchUtxoData"];

  if (indexerApiEndpoint !== undefined && indexerApiEndpoint !== "") {
    const { getMerkleProofFetcher, getBatchMerkleProofFetcher, getUtxoDataFetcher } =
      await import("./indexer");

    fetchMerkleProof = getMerkleProofFetcher({ apiEndpoint: indexerApiEndpoint });
    fetchBatchMerkleProof = getBatchMerkleProofFetcher({ apiEndpoint: indexerApiEndpoint });
    fetchUtxoData = getUtxoDataFetcher({ apiEndpoint: indexerApiEndpoint });
  }

  // Set up master seed storage (use overrides or defaults)
  const defaultMasterSeedStorage = getDefaultMasterSeedStorage();
  const defaultMasterSeedGenerator = getDefaultMasterSeedGenerator(signer);

  const masterSeedLoad = deps?.masterSeedStorage?.load ?? defaultMasterSeedStorage.load;
  const masterSeedStore = deps?.masterSeedStorage?.store ?? defaultMasterSeedStorage.store;
  const masterSeedGenerate = deps?.masterSeedStorage?.generate ?? defaultMasterSeedGenerator;

  // Create getMasterSeed convenience function
  const getMasterSeed = async (): Promise<MasterSeed> => {
    const loadResult = await masterSeedLoad();
    if (loadResult.exists) {
      return loadResult.seed;
    }
    const seed = await masterSeedGenerate();
    await masterSeedStore(seed);
    return seed;
  };

  // Set up key storage objects (all default no-ops for now)
  // Users can override these in deps when needed
  const masterViewingKeyStorage = {
    load: getDefaultKeyLoader<MasterViewingKey>(),
    store: getDefaultKeyStorer(),
    generate: notImplementedGenerator as () => Promise<MasterViewingKey>,
  };

  const poseidonPrivateKeyStorage = {
    load: getDefaultKeyLoader<PoseidonKey>(),
    store: getDefaultKeyStorer(),
    generate: notImplementedGenerator as () => Promise<PoseidonKey>,
  };

  const x25519PrivateKeyStorage = {
    load: getDefaultKeyLoader<X25519PrivateKey>(),
    store: getDefaultKeyStorer(),
    generate: notImplementedGenerator as () => Promise<X25519PrivateKey>,
  };

  const yearlyViewingKeyStorage = {
    load: getDefaultKeyLoader<YearlyViewingKey>(),
    store: getDefaultKeyStorer(),
    generate: notImplementedGenerator as () => Promise<YearlyViewingKey>,
  };

  const monthlyViewingKeyStorage = {
    load: getDefaultKeyLoader<MonthlyViewingKey>(),
    store: getDefaultKeyStorer(),
    generate: notImplementedGenerator as () => Promise<MonthlyViewingKey>,
  };

  const dailyViewingKeyStorage = {
    load: getDefaultKeyLoader<DailyViewingKey>(),
    store: getDefaultKeyStorer(),
    generate: notImplementedGenerator as () => Promise<DailyViewingKey>,
  };

  const mintViewingKeyStorage = {
    load: getDefaultKeyLoader<MintViewingKey>(),
    store: getDefaultKeyStorer(),
    generate: notImplementedGenerator as () => Promise<MintViewingKey>,
  };

  const rescueCommitmentBlindingFactorStorage = {
    load: getDefaultKeyLoader<Bn254FieldElement>(),
    store: getDefaultKeyStorer(),
    generate: notImplementedGenerator as () => Promise<Bn254FieldElement>,
  };

  const randomCommitmentFactorStorage = {
    load: getDefaultKeyLoader<Curve25519FieldElement>(),
    store: getDefaultKeyStorer(),
    generate: notImplementedGenerator as () => Promise<Curve25519FieldElement>,
  };

  // Assemble the fully constructed client
  const client: IUmbraClient = {
    signer,
    network,
    networkConfig,
    versions,
    offsets,
    accountInfoProvider,
    blockhashProvider,
    transactionForwarder,
    epochInfoProvider,
    computationMonitor,
    ...(fetchMerkleProof !== undefined && { fetchMerkleProof }),
    ...(fetchBatchMerkleProof !== undefined && { fetchBatchMerkleProof }),
    ...(fetchUtxoData !== undefined && { fetchUtxoData }),
    masterSeed: {
      load: masterSeedLoad,
      store: masterSeedStore,
      generate: masterSeedGenerate,
      getMasterSeed,
    },
    masterViewingKey: masterViewingKeyStorage,
    poseidonPrivateKey: poseidonPrivateKeyStorage,
    x25519PrivateKey: x25519PrivateKeyStorage,
    yearlyViewingKey: yearlyViewingKeyStorage,
    monthlyViewingKey: monthlyViewingKeyStorage,
    dailyViewingKey: dailyViewingKeyStorage,
    mintViewingKey: mintViewingKeyStorage,
    rescueCommitmentBlindingFactor: rescueCommitmentBlindingFactorStorage,
    randomCommitmentFactor: randomCommitmentFactorStorage,
  };

  // Eager mode: derive and cache the master seed before returning so the
  // signing prompt fires at construction time rather than at first use.
  if (!deferMasterSeedSignature) {
    await getMasterSeed();
  }

  return client;
}
