/**
 * Claim Staged SPL From Pool Implementation
 *
 * Recovers SPL tokens that were staged in the user's encrypted token account
 * when an MPC callback failed mid-flight. Without this, the tokens remain
 * locked in the pool's associated token account indefinitely.
 *
 * @remarks
 * ## Background: Staged Funds
 *
 * Confidential SPL token operations (deposits, transfers, withdrawals) follow
 * the dual-instruction MPC pattern:
 *
 * 1. **Handler** — Validates inputs, moves SPL tokens from the user into the
 *    pool's associated token account (ATA), and queues the Arcium MPC
 *    computation.
 * 2. **Callback** — Called asynchronously by the Arcium network once the MPC
 *    computation completes. Updates encrypted balances and finalises the
 *    operation.
 *
 * If the handler succeeds but the Arcium callback never arrives (e.g. due to
 * a network partition, insufficient compute budget, or an Arcium service
 * outage), the user's SPL tokens remain locked in the pool ATA as staged
 * funds. This instruction allows the original user to reclaim those tokens
 * without any MPC involvement — the on-chain program verifies ownership before
 * releasing.
 *
 * ## How It Differs from the SOL Variant
 *
 * - SOL staging: funds are held in the pool PDA (system account lamports).
 * - SPL staging: funds are held in the pool's **associated token account**
 *   (`poolSplAta`), which Codama auto-derives from `(pool, mint)`.
 * - The token program used for the transfer is also auto-detected from the
 *   mint discriminator (supports both Token and Token-2022).
 *
 * ## Codama Auto-Derived Accounts
 *
 * The Codama-generated helper resolves the following accounts automatically:
 * - `encryptedTokenAccount`: PDA `[SEED, user, mint]`
 * - `pool`: PDA `[Pool::SEED, mint]`
 * - `poolSplAta`: ATA with `authority = pool`, `mint = mint`
 * - `tokenProgram`: detected from the mint account discriminator
 *
 * ## Transaction Flow
 *
 * 1. Validate that `amount > 0`.
 * 2. Build the `claim_staged_spl_from_pool` instruction via the Codama helper.
 * 3. Assemble a versioned transaction and attach the latest blockhash.
 * 4. Partially sign with noop signers (placeholder for wallet), then complete
 *    signing via `signer.signTransaction`.
 * 5. Fire the optional `pre` callback, forward to the network, then fire the
 *    optional `post` callback.
 *
 * ## Security Notes
 *
 * - Only the user who owns the `encryptedTokenAccount` PDA can claim
 *   their own staged tokens; the on-chain program enforces ownership.
 * - No MPC or ZK proofs are required; this is a purely administrative
 *   recovery instruction.
 * - If `optionalData` is not provided, 32 zero bytes are used as the default.
 *
 * @packageDocumentation
 * @module implementation/umbra/services/user/claim-staged-spl-from-pool
 */

import {
  createNoopSigner,
  appendTransactionMessageInstructions,
  partiallySignTransactionMessageWithSigners,
  createTransactionMessage,
  pipe,
  setTransactionMessageFeePayer,
  setTransactionMessageLifetimeUsingBlockhash,
  type Instruction,
} from "@solana/kit";
import { getClaimStagedSplFromPoolInstructionAsync } from "@umbra-privacy/umbra-codama";
import type {
  ClaimStagedSplFromPoolFunction,
  GetClaimStagedSplFromPoolFunctionArgs,
  GetClaimStagedSplFromPoolFunctionDeps,
  SignableTransaction,
  TransactionCallbacks,
} from "../../interfaces";
import type { OptionalData32, TransactionSignature, U64 } from "../../../types";
import { TransactionError } from "../../../errors";

/* =============================================================================
 * CONSTANTS
 * ============================================================================= */

/**
 * Default optional data: 32 zero bytes used when the caller does not supply
 * application-specific metadata.
 *
 * @internal
 */
const DEFAULT_OPTIONAL_DATA_BYTES = new Uint8Array(32);

/* =============================================================================
 * FACTORY FUNCTION
 * ============================================================================= */

/**
 * Creates a function for recovering SPL tokens staged in a failed MPC callback.
 *
 * @remarks
 * This follows the SDK factory pattern: the factory is called once during
 * client setup to capture dependencies, and the returned function is called
 * at runtime to execute the recovery. All derived accounts (pool ATA, token
 * program, etc.) are resolved by the Codama-generated instruction builder;
 * the caller only provides the user-facing parameters.
 *
 * Dependency resolution order: explicit `deps` override takes precedence,
 * then the corresponding field on `client`.
 *
 * @param args - Required arguments containing the configured Umbra client.
 *   The client provides the wallet signer, blockhash provider, transaction
 *   forwarder, and network configuration.
 * @param deps - Optional dependency overrides. When provided, each override
 *   replaces the corresponding client-level default. Useful for testing or
 *   custom RPC routing.
 * @returns A `ClaimStagedSplFromPoolFunction` that, when called, builds,
 *   signs, and submits the recovery transaction on-chain.
 *
 * @example
 * ```typescript
 * import { getClaimStagedSplFromPoolFunction } from "@umbra-privacy/sdk";
 * import { address } from "@solana/kit";
 *
 * // Create the recovery function (once, at client setup)
 * const claimStagedSpl = getClaimStagedSplFromPoolFunction({ client });
 *
 * // Recover 1_000_000 micro-USDC of staged SPL tokens
 * const signature = await claimStagedSpl(
 *   address("EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v"), // USDC mint
 *   1_000_000n,                                                 // amount (token units)
 *   address("UserUsdcAtaAddressHere..."),                       // destinationAta
 * );
 * console.log("Recovery tx:", signature);
 * ```
 *
 * @example
 * ```typescript
 * // With optional data and lifecycle callbacks
 * const signature = await claimStagedSpl(
 *   usdcMint,
 *   500_000n,
 *   myUsdcAta,
 *   new Uint8Array(32),           // optionalData (32 bytes)
 *   {
 *     pre: async ({ transaction }) => console.log("Sending...", transaction),
 *     post: async ({ signature }) => console.log("Confirmed:", signature),
 *   },
 * );
 * ```
 *
 * @see {@link ClaimStagedSplFromPoolFunction} — the type of the returned function
 * @see {@link GetClaimStagedSplFromPoolFunctionArgs} — factory argument type
 * @see {@link GetClaimStagedSplFromPoolFunctionDeps} — injectable dependency type
 * @see {@link getClaimStagedSolFromPoolFunction} — analogous recovery for native SOL
 * @public
 */
export function getStagedSplRecovererFunction(
  args: GetClaimStagedSplFromPoolFunctionArgs,
  deps?: GetClaimStagedSplFromPoolFunctionDeps,
): ClaimStagedSplFromPoolFunction {
  const { client } = args;
  const { signer } = client;

  const getLatestBlockhash = deps?.rpc?.blockhashProvider ?? client.blockhashProvider;
  const transactionForwarder = deps?.rpc?.transactionForwarder ?? client.transactionForwarder;

  /**
   * Claims staged SPL tokens from the pool back to a destination ATA.
   *
   * @remarks
   * The Codama-generated instruction helper auto-derives:
   * - `encryptedTokenAccount`: PDA seeded with `[SEED, user, mint]`
   * - `pool`: PDA seeded with `[Pool::SEED, mint]`
   * - `poolSplAta`: ATA with `authority = pool`, `mint = mint`
   * - `tokenProgram`: detected from the mint account discriminator
   *
   * The on-chain handler verifies that the caller's wallet address matches the
   * user authority stored in the encrypted token account before transferring
   * tokens to `destinationAta`.
   *
   * @param mint - The SPL mint address whose pool holds the staged tokens.
   * @param amount - The number of token base units to recover. Must be greater
   *   than zero.
   * @param destinationAta - The associated token account (ATA) that will
   *   receive the recovered tokens. Must be owned by the caller and initialized
   *   for `mint`.
   * @param optionalData - An optional 32-byte payload for application-level
   *   metadata or tagging. Defaults to 32 zero bytes if not provided.
   * @param callbacks - Optional lifecycle hooks invoked before and after
   *   transaction submission.
   * @returns The transaction signature of the submitted recovery transaction.
   * @throws {@link TransactionError} if `amount` is zero.
   *
   * @example
   * ```typescript
   * const sig = await claimStagedSplFromPool(usdcMint, 1_000_000n, myUsdcAta);
   * ```
   *
   * @public
   */
  return async function claimStagedSplFromPool(
    mint,
    amount: U64,
    destinationAta,
    optionalData?: OptionalData32,
    callbacks?: TransactionCallbacks,
  ): Promise<TransactionSignature> {
    const userAddress = signer.address;

    // ================================================================
    // Step 1: Validate amount
    // ================================================================

    if (amount === 0n) {
      throw new TransactionError("amount must be greater than zero");
    }

    // ================================================================
    // Step 2: Build the instruction
    //
    // Codama auto-derives:
    //   - encryptedTokenAccount: PDA [SEED, user, mint]
    //   - pool: PDA [Pool::SEED, mint]
    //   - poolSplAta: ATA with authority=pool, mint=mint
    //   - tokenProgram: detected from mint
    // ================================================================

    const noopSigner = createNoopSigner(userAddress);
    const instruction: Instruction = await getClaimStagedSplFromPoolInstructionAsync({
      feePayer: noopSigner,
      user: noopSigner,
      mint,
      destinationAta,
      amount: { first: amount },
      optionalData: { first: optionalData ?? DEFAULT_OPTIONAL_DATA_BYTES },
    }, { programAddress: client.networkConfig.programId });

    // ================================================================
    // Step 3: Build, sign, and forward the transaction
    // ================================================================

    const latestBlockhash = await getLatestBlockhash();

    const transactionMessage = pipe(
      createTransactionMessage({ version: 0 }),
      (m) => setTransactionMessageFeePayer(userAddress, m),
      (m) => setTransactionMessageLifetimeUsingBlockhash(latestBlockhash, m),
      (m) => appendTransactionMessageInstructions([instruction], m),
    );

    const partiallySignedTransaction =
      await partiallySignTransactionMessageWithSigners(transactionMessage);

    const signedTransaction = await signer.signTransaction(
      partiallySignedTransaction as SignableTransaction,
    );

    await callbacks?.pre?.(signedTransaction);
    const signatures = await transactionForwarder.forwardInParallel([signedTransaction]);
    const signature = signatures[0];
    await callbacks?.post?.(signedTransaction, signature);
    return signature;
  };
}
