/**
 * Encrypted Token Account Balance Fetcher Implementation
 *
 * This module provides the implementation for fetching and decrypting
 * Arcium encrypted token account balances from the Solana blockchain.
 *
 * @remarks
 * ## Decryption Modes and What This Function Can Decrypt
 *
 * Umbra encrypted token accounts exist in two modes:
 *
 * - **MXE mode**: The balance ciphertext is encrypted solely under the Arcium
 *   network's X25519 public key. Client-side decryption is impossible; the user
 *   must submit an MPC query to retrieve their balance. This function returns
 *   `{ state: "mxe" }` for these accounts.
 *
 * - **Shared mode**: The balance ciphertext is protected by the Rescue cipher
 *   under the user's own X25519 private key (in addition to the Arcium network
 *   key). This function can decrypt these balances entirely client-side using
 *   the user's derived X25519 private key.
 *
 * ## Rescue Cipher Decryption
 *
 * For shared-mode accounts, the decryption process is:
 * 1. Derive the user's account-level X25519 private key via
 *    `getUserAccountX25519KeypairDeriver` (lazy, cached across calls).
 * 2. Construct a Rescue cipher decryptor bound to both the user's X25519
 *    private key and the Arcium network's X25519 public key
 *    (`client.networkConfig.mxePubkey`) via `getRescueDecryptorFromPrivateKey`.
 * 3. Extract the stored `nonce` and 32-byte `balance` ciphertext from the
 *    decoded token account.
 * 4. Deserialise the 32-byte ciphertext as a little-endian `bigint`
 *    (`RcCiphertext`).
 * 5. Call the Rescue decryptor with `[balanceCiphertext]` and `nonce` to obtain
 *    a single-element plaintext array.
 * 6. Cast the plaintext to `U64`.
 *
 * ## Batch Processing
 *
 * The function accepts a `readonly Address[]` of mints and processes them
 * efficiently:
 * 1. Derives all token account PDAs in parallel.
 * 2. Batch-fetches all account data in a single `accountInfoProvider` call.
 * 3. Iterates accounts, decoding and decrypting only those in shared mode.
 * 4. Returns a `Map<Address, QueryEncryptedBalanceResult>` keyed by mint.
 *
 * The decryptor is lazily initialised on the first shared-mode account
 * encountered and then cached for the lifetime of the returned closure.
 *
 * ## Result States
 *
 * Each mint in the returned map maps to one of:
 * - `{ state: "shared", balance: U64 }` — decrypted plaintext balance
 * - `{ state: "mxe" }` — encrypted under network key; cannot decrypt client-side
 * - `{ state: "uninitialized" }` — Arcium balance not yet initialised (Bit 4 = 0)
 * - `{ state: "non_existent" }` — account PDA does not exist on-chain
 *
 * ## Status Bit Reference
 *
 * From the Rust on-chain definition:
 * - Bit 0: `is_initialised`
 * - Bit 1: `is_active_for_confidential_usage`
 * - Bit 2: `is_active_for_anonymous_usage`
 * - Bit 3: `is_shared_mode` (TRUE = Shared, FALSE = MXE)
 * - Bit 4: `is_arcium_balance_initialised`
 *
 * @packageDocumentation
 * @module implementation/umbra/services/query/token-account
 */

import type { Account, Address, MaybeEncodedAccount } from "@solana/kit";
import {
  decodeEncryptedTokenAccount,
  type EncryptedTokenAccount,
} from "@umbra-privacy/umbra-codama";
import type {
  QueryEncryptedBalanceFunction as QueryEncryptedBalanceFunction,
  QueryEncryptedBalanceResult,
  GetQueryEncryptedBalanceFunctionArgs as GetQueryEncryptedBalanceFunctionArgs,
  GetQueryEncryptedBalanceFunctionDeps as GetQueryEncryptedBalanceFunctionDeps,
} from "../../interfaces";
import type { U64 } from "../../../common/types";
import type { RcCiphertext, RcEncryptionNonce } from "../../../types/cryptography";
import { findEncryptedTokenAccountPda } from "../../../common/pda/user";
import { getUserAccountX25519KeypairDeriver } from "../../../crypto/key-derivation";
import { getRescueDecryptorFromPrivateKey } from "../../../crypto/rescue";
import { getByteAt } from "../../../common/type-helpers";
import { QueryError } from "../../../errors";

/* =============================================================================
 * HELPER FUNCTIONS
 * ============================================================================= */

/**
 * Converts a little-endian byte array to a bigint.
 *
 * @remarks
 * The Rescue cipher stores ciphertexts and plaintexts as field elements
 * serialised in little-endian byte order. This function reconstructs the
 * canonical `bigint` value from that representation.
 *
 * Handles both `Uint8Array` instances and arbitrary `ArrayLike<number>` objects
 * (e.g. the `ReadonlyUint8Array` type produced by the Codama decoder).
 *
 * @param bytes - The byte array in little-endian format.
 * @returns The reconstructed `bigint` value.
 *
 * @internal
 */
function bytesToBigIntLe(bytes: Uint8Array | ArrayLike<number>): bigint {
  // Convert to Uint8Array if it's an ArrayLike (e.g., ReadonlyUint8Array from codama)
  const array = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  let result = 0n;
  const length = array.length;
  for (let index = length - 1; index >= 0; index--) {
    const byte = getByteAt(array, index);
    result = (result << 8n) | BigInt(byte);
  }
  return result;
}

/**
 * Extracts the nonce from the decoded token account.
 *
 * @remarks
 * The Codama type wraps the nonce in a `{ first: bigint }` object. This helper
 * unwraps it to the raw `RcEncryptionNonce` type consumed by the Rescue
 * decryptor.
 *
 * @param account - Decoded token account data from the Codama decoder.
 * @returns The nonce as `RcEncryptionNonce`.
 *
 * @internal
 */
function extractNonce(account: EncryptedTokenAccount): RcEncryptionNonce {
  // The nonce is stored as { first: bigint } in codama types
  return account.nonce.first as RcEncryptionNonce;
}

/**
 * Extracts the encrypted balance ciphertext from the decoded token account.
 *
 * @remarks
 * The balance is stored on-chain as a 32-byte Rescue ciphertext in
 * little-endian order. This helper deserialises the bytes to a `bigint`
 * (`RcCiphertext`) suitable for passing to the Rescue decryptor.
 *
 * @param account - Decoded token account data from the Codama decoder.
 * @returns The balance ciphertext as `RcCiphertext` (a `bigint` branded type).
 *
 * @internal
 */
function extractBalanceCiphertext(account: EncryptedTokenAccount): RcCiphertext {
  // The balance is stored as { first: ReadonlyUint8Array } in codama types
  // Convert to bigint for decryption
  const balanceBytes = account.balance.first;
  return bytesToBigIntLe(balanceBytes) as RcCiphertext;
}

/* =============================================================================
 * STATUS BIT CONSTANTS
 * ============================================================================= */

/**
 * Status bit positions for the `EncryptedTokenAccount.statusBits` field.
 *
 * @remarks
 * From the Rust on-chain definition:
 * - Bit 0: `is_initialised`
 * - Bit 1: `is_active_for_confidential_usage`
 * - Bit 2: `is_active_for_anonymous_usage`
 * - Bit 3: `is_shared_mode` (TRUE = Shared, FALSE = MXE)
 * - Bit 4: `is_arcium_balance_initialised`
 *
 * Only the two bits relevant to balance decryption are listed here.
 *
 * @internal
 */
const TOKEN_ACCOUNT_STATUS_BITS = {
  IS_INITIALISED: 0,
  IS_SHARED_MODE: 3,
  IS_ARCIUM_BALANCE_INITIALISED: 4,
} as const;

/**
 * Checks if a specific bit is set in a value.
 *
 * @remarks
 * Accepts both `number` and `bigint` to handle the codama-decoded
 * `statusBits.first` type. Uses `BigInt` arithmetic throughout to avoid
 * 32-bit integer truncation.
 *
 * @param value - The value to check (can be number or bigint).
 * @param bitPosition - The zero-indexed bit position to check.
 * @returns `true` if the bit at `bitPosition` is set; `false` otherwise.
 *
 * @internal
 */
function isBitSet(value: number | bigint, bitPosition: number): boolean {
  return (BigInt(value) & (1n << BigInt(bitPosition))) !== 0n;
}

/* =============================================================================
 * FACTORY FUNCTION
 * ============================================================================= */

/**
 * Creates a function for fetching and decrypting encrypted token account balances.
 *
 * @remarks
 * This factory creates a fetcher that:
 * 1. Derives token account PDAs for each mint using the user's address
 * 2. Batch fetches all account data using the AccountInfoProvider
 * 3. Decodes the raw bytes using the codama decoder
 * 4. Decrypts the balance using the provided RcDecryptorFunction
 * 5. Returns a map of results for each mint
 *
 * The Rescue decryptor is lazily initialised on first use: the X25519 private
 * key is derived only when a shared-mode account is actually encountered. It is
 * then cached for the lifetime of the closure so subsequent calls to the
 * returned function do not re-derive the key.
 *
 * If a custom `rcDecryptor` is provided in `deps`, it is used directly without
 * any key derivation.
 *
 * Dependency resolution order: explicit `deps` override takes precedence,
 * then the corresponding field on `client`.
 *
 * @param args - Required arguments containing the configured Umbra client.
 *   The client provides the wallet signer, account info provider, and network
 *   configuration (including the Arcium MXE public key used in Rescue decryption).
 * @param deps - Optional dependency overrides. Useful for injecting a custom
 *   `rcDecryptor` or `accountInfoProvider` in tests.
 * @returns A `QueryEncryptedBalanceFunction` that, when called, fetches and
 *   (where possible) decrypts balances for the given mints.
 *
 * @example
 * ```typescript
 * import { getQueryEncryptedBalanceFunction } from "@umbra-privacy/sdk";
 * import { address } from "@solana/kit";
 *
 * // Simple usage with defaults derived from client
 * const fetchBalances = getQueryEncryptedBalanceFunction({ client });
 *
 * // Fetch balances for multiple mints
 * const balances = await fetchBalances([usdcMint, usdtMint]);
 *
 * for (const [mint, result] of balances) {
 *     if (result.state === 'shared') {
 *         console.log(`${mint}: ${result.balance}`);
 *     } else {
 *         console.log(`${mint}: ${result.state}`);
 *     }
 * }
 * ```
 *
 * @example
 * ```typescript
 * // Usage with custom dependencies
 * const fetchBalances = getQueryEncryptedBalanceFunction(
 *     { client },
 *     {
 *         accountInfoProvider: customProvider,
 *         rcDecryptor: customDecryptor,
 *     }
 * );
 * ```
 *
 * @example
 * ```typescript
 * // Check total portfolio value (only shared accounts can be decrypted)
 * const mints = [usdcMint, usdtMint, solMint];
 * const balances = await fetchBalances(mints);
 *
 * let totalValue = 0n;
 * for (const [_, result] of balances) {
 *     if (result.state === 'shared') {
 *         totalValue += result.balance;
 *     }
 * }
 * console.log(`Total portfolio: ${totalValue}`);
 * ```
 *
 * @see {@link QueryEncryptedBalanceFunction} — the type of the returned function
 * @see {@link QueryEncryptedBalanceResult} — the discriminated-union result type
 * @see {@link GetQueryEncryptedBalanceFunctionArgs} — factory argument type
 * @see {@link GetQueryEncryptedBalanceFunctionDeps} — injectable dependency type
 * @see {@link getConvertToSharedEncryptionFunction} — converts MXE accounts so balances can be read
 * @see {@link getQueryUserAccountFunction} — fetches the parent user account state
 * @public
 */
export function getEncryptedBalanceQuerierFunction(
  args: GetQueryEncryptedBalanceFunctionArgs,
  deps?: GetQueryEncryptedBalanceFunctionDeps,
): QueryEncryptedBalanceFunction {
  const { client } = args;

  // Get the user address from the client's signer
  const userAddress = client.signer.address;

  // Create default account info provider if not provided
  const accountInfoProvider = deps?.accountInfoProvider ?? client.accountInfoProvider;

  // Create X25519 private key generator for deriving decryption key
  const tokenX25519KeypairDeriver = getUserAccountX25519KeypairDeriver({
    client,
  });

  // Cache for the decryptor (lazy initialization)
  let cachedDecryptor: Awaited<ReturnType<typeof getRescueDecryptorFromPrivateKey>> | null = null;

  /**
   * Gets or creates the Rescue decryptor.
   *
   * @remarks
   * If a custom `rcDecryptor` was provided in `deps`, it is returned directly
   * without any key derivation. Otherwise, the X25519 private key is derived
   * from the user's master seed on first call and the resulting decryptor is
   * cached in the closure. Subsequent calls return the cached instance.
   *
   * The decryptor is bound to both the user's X25519 private key and the Arcium
   * network's X25519 public key (`client.networkConfig.mxePubkey`). Both are
   * required to reconstruct the shared secret used by the Rescue cipher.
   *
   * @returns The Rescue decryptor function ready to accept `(ciphertexts, nonce)`.
   *
   * @internal
   */
  async function getDecryptor(): Promise<Awaited<ReturnType<typeof getRescueDecryptorFromPrivateKey>>> {
    // Use provided decryptor if available
    if (deps?.rcDecryptor !== undefined) {
      return deps.rcDecryptor;
    }

    // Lazy initialization of default decryptor
    if (cachedDecryptor === null) {
      let keypairResult: Awaited<ReturnType<typeof tokenX25519KeypairDeriver>>;
      try {
        keypairResult = await tokenX25519KeypairDeriver();
      } catch (error) {
        throw new QueryError(
          "key-derivation",
          `Failed to derive X25519 keypair: ${error instanceof Error ? error.message : String(error)}`,
          error instanceof Error ? error : undefined,
        );
      }
      const x25519PrivateKey = keypairResult.x25519Keypair.privateKey;
      cachedDecryptor = getRescueDecryptorFromPrivateKey(x25519PrivateKey, {
        umbraX25519PublicKey: client.networkConfig.mxePubkey,
      });
    }

    return cachedDecryptor;
  }

  /**
   * Fetches and decrypts the encrypted token account balances for the given mints.
   *
   * @remarks
   * Empty input returns an empty map immediately without any network calls.
   * For MXE-mode accounts, the result is `{ state: "mxe" }` — no decryption
   * is attempted and the Rescue key derivation is not triggered.
   *
   * The decryptor is only lazily initialised when the first shared-mode account
   * is encountered, avoiding unnecessary key derivation if all accounts are in
   * MXE mode.
   *
   * @param mints - The list of SPL mint addresses whose encrypted balances to
   *   fetch. An empty array returns an empty map immediately.
   * @returns A `Map<Address, QueryEncryptedBalanceResult>` where:
   *   - Shared-mode accounts have `state: "shared"` and a `balance: U64` field.
   *   - MXE-mode accounts have `state: "mxe"` (cannot decrypt client-side).
   *   - Uninitialised accounts have `state: "uninitialized"`.
   *   - Non-existent accounts have `state: "non_existent"`.
   *
   * @example
   * ```typescript
   * const results = await queryEncryptedBalance([usdcMint]);
   * const usdcResult = results.get(usdcMint);
   * if (usdcResult?.state === "shared") {
   *   console.log("USDC balance:", usdcResult.balance);
   * }
   * ```
   *
   * @param options - Optional. Pass `{ accountInfoCommitment }` to override the
   *   default `"confirmed"` commitment level for account reads.
   * @public
   */
  return async function queryEncryptedBalance(
    mints: readonly Address[],
  
    options?: { readonly accountInfoCommitment?: "processed" | "confirmed" | "finalized" }): Promise<Map<Address, QueryEncryptedBalanceResult>> {
    const accountInfoCommitment = options?.accountInfoCommitment ?? "confirmed";
    const results = new Map<Address, QueryEncryptedBalanceResult>();

    if (mints.length === 0) {
      return results;
    }

    // Step 1: Derive token account PDAs for all mints in parallel
    let pdaDerivations: { mint: Address; pda: Address }[];
    try {
      pdaDerivations = await Promise.all(
        mints.map(async (mint) => ({
          mint,
          pda: await findEncryptedTokenAccountPda(
            userAddress,
            mint,
            client.networkConfig.programId,
          ),
        })),
      );
    } catch (error) {
      throw new QueryError(
        "pda-derivation",
        `Failed to derive token account PDAs: ${error instanceof Error ? error.message : String(error)}`,
        error instanceof Error ? error : undefined,
      );
    }

    // Create a map from PDA to mint for reverse lookup
    const pdaToMint = new Map<Address, Address>();
    const pdas: Address[] = [];
    for (const { mint, pda } of pdaDerivations) {
      pdaToMint.set(pda, mint);
      pdas.push(pda);
    }

    // Step 2: Batch fetch all account data
    let accountMap: Awaited<ReturnType<typeof accountInfoProvider>>;
    try {
      accountMap = await accountInfoProvider(pdas);
    } catch (error) {
      throw new QueryError(
        "account-fetch",
        `Failed to fetch token account data: ${error instanceof Error ? error.message : String(error)}`,
        error instanceof Error ? error : undefined,
      );
    }

    // Step 3: Process each account
    for (const { mint, pda } of pdaDerivations) {
      const maybeAccount: MaybeEncodedAccount<Address> | undefined = accountMap.get(pda);

      // Check if account exists

       
      if (maybeAccount === undefined || !maybeAccount.exists || maybeAccount.data === undefined) {
        results.set(mint, { state: "non_existent" });
        continue;
      }

      // Step 4: Decode the account data using codama
      let decodedAccount: Account<EncryptedTokenAccount, string>;
      try {
        decodedAccount = decodeEncryptedTokenAccount(
          maybeAccount as unknown as MaybeEncodedAccount<Address> & {
            readonly exists: true;
          },
        ) as Account<EncryptedTokenAccount, string>;
      } catch (error) {
        throw new QueryError(
          "account-decode",
          `Failed to decode token account data for mint ${mint}: ${error instanceof Error ? error.message : String(error)}`,
          error instanceof Error ? error : undefined,
        );
      }

      // Step 5: Check status bits to determine account state
      const statusBits = decodedAccount.data.statusBits.first;

      // Check if Arcium balance is initialized (bit 4)
      if (!isBitSet(statusBits, TOKEN_ACCOUNT_STATUS_BITS.IS_ARCIUM_BALANCE_INITIALISED)) {
        results.set(mint, { state: "uninitialized" });
        continue;
      }

      // Check if shared mode (bit 3)
      // If not shared mode, it's MXE mode - cannot decrypt client-side
      if (!isBitSet(statusBits, TOKEN_ACCOUNT_STATUS_BITS.IS_SHARED_MODE)) {
        results.set(mint, { state: "mxe" });
        continue;
      }

      // Step 6: Shared mode - decrypt the balance
      // Get the decryptor (lazy initialization, only when needed)
      const rcDecryptor = await getDecryptor();

      // Extract nonce and encrypted balance
      const nonce = extractNonce(decodedAccount.data);
      const balanceCiphertext = extractBalanceCiphertext(decodedAccount.data);

      // Decrypt the balance
      // The balance is a single Rescue ciphertext element
      let plaintexts: Awaited<ReturnType<typeof rcDecryptor>>;
      try {
        plaintexts = await rcDecryptor([balanceCiphertext], nonce);
      } catch (error) {
        throw new QueryError(
          "decryption",
          `Failed to decrypt balance for mint ${mint}: ${error instanceof Error ? error.message : String(error)}`,
          error instanceof Error ? error : undefined,
        );
      }

      // The decrypted balance is the first (and only) plaintext
      const decryptedBalance = plaintexts[0];

       
      if (decryptedBalance === undefined) {
        // This shouldn't happen if decryption succeeded, but handle it gracefully
        results.set(mint, { state: "non_existent" });
        continue;
      }

      // Convert the decrypted plaintext to U64
      // RcPlaintext is a bigint, we need to ensure it fits in U64
      const balance = BigInt(decryptedBalance) as U64;

      results.set(mint, {
        state: "shared",
        balance,
      });
    }

    return results;
  };
}
