/**
 * Create User-Granted Compliance Grant Implementation
 *
 * Creates a compliance grant PDA that authorises a receiver to use their X25519 key
 * to request re-encryption of the granter's shared ciphertexts.
 *
 * The granter must prove identity by signing with the Ed25519 key whose birational
 * X25519 equivalent equals their registered `x25519_mvk_public_key`.
 *
 * @remarks
 * ## Compliance Grant Privacy Model
 *
 * Umbra supports confidential token accounts in two modes:
 * - **MXE mode**: Only the Arcium MPC network can decrypt balances.
 * - **Shared mode**: Both the Arcium MPC network and the user (via their X25519
 *   private key) can decrypt.
 *
 * A **user-granted compliance grant** is a marker PDA that authorises a named
 * third-party (the receiver) to request re-encryption of the granter's
 * **shared-mode** ciphertexts. Concretely, the receiver can later call
 * `reencrypt_user_grant_v11` on-chain, providing the grant PDA
 * as proof of authorisation, which causes the Arcium MPC network to re-encrypt
 * the provided ciphertexts from the granter's X25519 key to the receiver's
 * X25519 key.
 *
 * ### What the Grant Enables
 *
 * - The receiver can read the granter's **shared-mode** encrypted balances and
 *   transaction amounts, but only for ciphertexts they explicitly submit.
 * - Re-encryption is performed by Arcium MPC nodes, so neither the receiver
 *   nor a relayer ever sees the granter's X25519 private key.
 *
 * ### What the Grant Does NOT Enable
 *
 * - The grant does **not** allow the receiver to move, spend, or otherwise
 *   control the granter's funds.
 * - The grant does **not** expose the granter's MXE-mode balances; only
 *   shared-mode ciphertexts can be re-encrypted via this grant type.
 * - The grant does **not** provide access to the granter's X25519 private key;
 *   all decryption occurs inside the Arcium MPC enclave.
 *
 * ## Threat Model
 *
 * Even if a malicious relayer intercepts the transaction before it is
 * submitted, they cannot modify the grant's authorised receiver because the
 * Ed25519 proving key signature covers the receiver address. Attempting to
 * swap the receiver address would invalidate the signature and cause the
 * on-chain instruction to fail.
 *
 * ## Identity Proof: Ed25519 / X25519 Birational Equivalence
 *
 * The granter's identity is established on-chain via their registered
 * `x25519_mvk_public_key` (Master Viewing Key X25519 public key). However,
 * Solana transactions cannot carry raw X25519 signatures, so Umbra uses the
 * birational equivalence between Curve25519 (Ed25519) and Curve25519 (X25519)
 * to derive a provable Ed25519 keypair whose public key maps to the registered
 * X25519 key. The granter signs with this Ed25519 key (`mvkProvingSigner`),
 * and the on-chain program verifies the signature and confirms the Ed25519
 * public key birationally maps to the stored MVK.
 *
 * ## Grant PDA Structure
 *
 * The compliance grant PDA is seeded by:
 * - `granterX25519` — granter's MVK X25519 public key (32 bytes)
 * - `nonce` — caller-provided nonce to allow multiple grants to the same receiver
 * - `receiverX25519` — receiver's X25519 public key (32 bytes)
 *
 * The PDA's existence on-chain is the grant itself; no structured data is stored.
 *
 * ## Transaction Flow
 *
 * 1. Derive the MVK proving keypair via `masterViewingKeyX25519KeypairDeriver`.
 * 2. Derive the granter's `EncryptedUserAccount` PDA explicitly from the
 *    wallet address (Codama would otherwise use the proving signer's address).
 * 3. Build the `create_user_granted_compliance_grant` instruction.
 * 4. Add a `SetComputeUnitLimit(1_200_000)` instruction for Ed25519 signature
 *    verification overhead.
 * 5. Partially sign (MVK proving signer auto-signs), then complete with wallet.
 * 6. Fire pre-callback, forward, fire post-callback.
 *
 * @packageDocumentation
 * @module implementation/umbra/services/compliance/create-user-granted-compliance-grant
 */

import {
  createNoopSigner,
  createKeyPairSignerFromPrivateKeyBytes,
  appendTransactionMessageInstructions,
  partiallySignTransactionMessageWithSigners,
  createTransactionMessage,
  pipe,
  setTransactionMessageFeePayer,
  setTransactionMessageLifetimeUsingBlockhash,
  type Address,
  type Instruction,
} from "@solana/kit";
import { getCreateUserGrantInstructionAsync } from "@umbra-privacy/umbra-codama";
import type {
  CreateUserGrantedComplianceGrantFunction,
  GetCreateUserGrantedComplianceGrantFunctionArgs,
  GetCreateUserGrantedComplianceGrantFunctionDeps,
  SignableTransaction,
  TransactionCallbacks,
} from "../../interfaces";
import type {
  OptionalData32,
  RcEncryptionNonce,
  TransactionSignature,
  X25519PublicKey,
} from "../../../types";
import { findEncryptedUserAccountPda } from "../../../common/pda/user";
import { getMasterViewingKeyX25519KeypairDeriver } from "../../../crypto/key-derivation";
import { createSetComputeUnitLimitInstruction } from "../../../solana/constants";

/* =============================================================================
 * CONSTANTS
 * ============================================================================= */

/**
 * Default optional data: 32 zero bytes used when the caller does not supply
 * application-specific metadata.
 *
 * @internal
 */
const DEFAULT_OPTIONAL_DATA_BYTES = new Uint8Array(32);

/* =============================================================================
 * FACTORY FUNCTION
 * ============================================================================= */

/**
 * Creates a function for granting a receiver viewing access to shared ciphertexts.
 *
 * @remarks
 * This follows the SDK factory pattern: the factory is called once during
 * client setup to capture dependencies, and the returned function is called
 * at runtime to create the grant. The factory resolves the MVK keypair
 * generator at construction time; the returned function calls it once per
 * grant creation.
 *
 * Dependency resolution order: explicit `deps` override takes precedence,
 * then the corresponding field on `client`.
 *
 * @param args - Required arguments containing the configured Umbra client.
 *   The client provides the wallet signer, blockhash provider, transaction
 *   forwarder, and network configuration.
 * @param deps - Optional dependency overrides. When provided, each override
 *   replaces the corresponding client-level default. Particularly useful for
 *   injecting a custom `masterViewingKeyX25519KeypairDeriver` in tests.
 * @returns A `CreateUserGrantedComplianceGrantFunction` that, when called,
 *   builds, signs, and submits the grant creation transaction on-chain.
 *
 * @example
 * ```typescript
 * import { getCreateUserGrantedComplianceGrantFunction } from "@umbra-privacy/sdk";
 * import { address } from "@solana/kit";
 *
 * // Create the grant function (once, at client setup)
 * const createGrant = getCreateUserGrantedComplianceGrantFunction({ client });
 *
 * // Grant viewing access to an auditor
 * const signature = await createGrant(
 *   address("AuditorWalletAddressHere..."),   // receiver (auditor's wallet)
 *   myX25519PublicKey,                        // granter's MVK X25519 public key
 *   auditorX25519PublicKey,                   // receiver's X25519 public key
 *   BigInt(Date.now()),                        // nonce (e.g. timestamp for uniqueness)
 * );
 * console.log("Grant created:", signature);
 * ```
 *
 * @example
 * ```typescript
 * // Creating multiple grants with different nonces for the same receiver
 * const grantA = await createGrant(receiver, myX25519, auditorX25519, 1n);
 * const grantB = await createGrant(receiver, myX25519, auditorX25519, 2n);
 * // Both PDAs coexist independently on-chain
 * ```
 *
 * @see {@link CreateUserGrantedComplianceGrantFunction} — the type of the returned function
 * @see {@link GetCreateUserGrantedComplianceGrantFunctionArgs} — factory argument type
 * @see {@link GetCreateUserGrantedComplianceGrantFunctionDeps} — injectable dependency type
 * @see {@link getDeleteUserGrantedComplianceGrantFunction} — revocation counterpart
 * @see {@link getReencryptUserGrantV11Function} — uses this grant for re-encryption
 * @public
 */
export function getComplianceGrantIssuerFunction(
  args: GetCreateUserGrantedComplianceGrantFunctionArgs,
  deps?: GetCreateUserGrantedComplianceGrantFunctionDeps,
): CreateUserGrantedComplianceGrantFunction {
  const { client } = args;
  const { signer } = client;

  const getLatestBlockhash = deps?.rpc?.blockhashProvider ?? client.blockhashProvider;
  const transactionForwarder = deps?.rpc?.transactionForwarder ?? client.transactionForwarder;
  const masterViewingKeyX25519KeypairDeriver =
    deps?.keys?.masterViewingKeyX25519KeypairDeriver ??
    getMasterViewingKeyX25519KeypairDeriver({ client });

  /**
   * Creates a user-granted compliance grant on-chain.
   *
   * @remarks
   * ## Two-Signer Pattern
   *
   * This instruction requires two signatures:
   * 1. **Wallet signer** (`feePayer`) — pays transaction fees; proves wallet ownership.
   * 2. **MVK proving signer** (`granter`) — an Ed25519 keypair derived from the
   *    master viewing key seed whose public key birationally maps to
   *    `granterX25519`. This signature proves that the caller controls the
   *    X25519 key they are asserting as the granter identity.
   *
   * The `partiallySignTransactionMessageWithSigners` call handles the MVK
   * proving signer automatically (it is a `KeyPairSigner`). The wallet signer
   * is applied afterward via `signer.signTransaction`.
   *
   * ## PDA Derivation Override
   *
   * The `granterUserAccount` PDA must be derived from the **wallet address**,
   * not from the MVK proving signer address (which is different). Codama's
   * auto-derivation would use the `granter` account address (the proving
   * signer), which is incorrect. This function explicitly computes the PDA
   * using `findEncryptedUserAccountPda(userAddress, programId)`.
   *
   * @param receiver - The Solana wallet address of the party being granted
   *   viewing access. This address identifies the receiver on-chain.
   * @param granterX25519 - The granter's Master Viewing Key X25519 public key
   *   (32 bytes). Used as part of the PDA seed and verified against the
   *   granter's registered MVK in the on-chain user account.
   * @param receiverX25519 - The receiver's X25519 public key (32 bytes). Used
   *   as part of the PDA seed and stored in the grant for use during
   *   re-encryption operations.
   * @param nonce - A caller-provided nonce that disambiguates multiple grants
   *   to the same receiver with the same X25519 keys. Use a timestamp, counter,
   *   or random value.
   * @param optionalData - An optional 32-byte payload for application-level
   *   metadata or tagging. Defaults to 32 zero bytes if not provided.
   * @param callbacks - Optional lifecycle hooks invoked before and after
   *   transaction submission.
   * @returns The transaction signature of the submitted grant creation transaction.
   *
   * @example
   * ```typescript
   * const sig = await createUserGrantedComplianceGrant(
   *   auditorAddress,
   *   myMvkX25519,
   *   auditorX25519,
   *   42n,
   * );
   * ```
   *
   * @public
   */
  return async function createUserGrantedComplianceGrant(
    receiver: Address,
    granterX25519: X25519PublicKey,
    receiverX25519: X25519PublicKey,
    nonce: RcEncryptionNonce,
    optionalData?: OptionalData32,
    callbacks?: TransactionCallbacks,
  ): Promise<TransactionSignature> {
    const userAddress = signer.address;
    const programId = client.networkConfig.programId;

    // ================================================================
    // Step 1: Derive the MVK proving signer from the Ed25519 seed
    // ================================================================

    const keypairResult = await masterViewingKeyX25519KeypairDeriver();
    const mvkProvingSigner = await createKeyPairSignerFromPrivateKeyBytes(
      keypairResult.ed25519Keypair.seed,
    );

    // ================================================================
    // Step 2: Derive the granter user account PDA from wallet address
    // The Codama auto-derivation uses granter.address (proving signer),
    // which is wrong — we must pass the wallet-derived PDA explicitly.
    // ================================================================

    const _granterUserAccount = await findEncryptedUserAccountPda(userAddress, programId);

    // ================================================================
    // Step 3: Build the instruction
    // ================================================================

    const noopSigner = createNoopSigner(userAddress);
    const instruction: Instruction = await getCreateUserGrantInstructionAsync({
      granterX25519ProvingSigner: mvkProvingSigner,
      feePayer: noopSigner,
      nonce: { first: nonce },
      granterX25519: { first: granterX25519 },
      receiverX25519: { first: receiverX25519 },
      optionalData: { first: optionalData ?? DEFAULT_OPTIONAL_DATA_BYTES },
    }, { programAddress: client.networkConfig.programId });

    // ================================================================
    // Step 4: Build, sign, and forward the transaction
    // ================================================================

    const latestBlockhash = await getLatestBlockhash();

    const computeBudgetInstruction = createSetComputeUnitLimitInstruction(1_200_000);

    const transactionMessage = pipe(
      createTransactionMessage({ version: 0 }),
      (m) => setTransactionMessageFeePayer(userAddress, m),
      (m) => setTransactionMessageLifetimeUsingBlockhash(latestBlockhash, m),
      (m) => appendTransactionMessageInstructions([computeBudgetInstruction, instruction], m),
    );

    // mvkProvingSigner (KeyPairSigner) auto-signs here; wallet noop slot stays empty
    const partiallySignedTransaction =
      await partiallySignTransactionMessageWithSigners(transactionMessage);

    const signedTransaction = await signer.signTransaction(
      partiallySignedTransaction as SignableTransaction,
    );

    await callbacks?.pre?.(signedTransaction);
    const signatures = await transactionForwarder.forwardInParallel([signedTransaction]);
    const signature = signatures[0];
    await callbacks?.post?.(signedTransaction, signature);
    return signature;
  };
}
