/**
 * Default Storage Implementations
 *
 * This module provides default implementations for key storage functions.
 * - Master seed: in-memory closure-based storage
 * - Other keys: no-op storage (always derive fresh, never persist)
 *
 * @module common/storage
 * @since 2.0.0
 */

import type {
  LoadResult,
  StoreResult,
  MasterSeed,
  MasterSeedLoaderFunction,
  MasterSeedStorerFunction,
  MasterSeedGeneratorFunction,
} from "../types";
import type { IUmbraSigner } from "../umbra/interfaces";
import { kmac256 as defaultKmac256 } from "@noble/hashes/sha3-addons.js";
import { assertMasterSeed } from "../types/cryptography";
import { UMBRA_MESSAGE_TO_SIGN } from "../umbra/constants";

/* =============================================================================
 * MASTER SEED DEFAULT STORAGE
 * ============================================================================= */

/**
 * Gets default in-memory storage for master seed.
 *
 * @remarks
 * Uses closure-based storage scoped to the function invocation.
 * The seed persists only in memory and is lost when the application closes.
 *
 * @returns Object with loader and storer functions
 */
export function getDefaultMasterSeedStorage(): {
  readonly load: MasterSeedLoaderFunction;
  readonly store: MasterSeedStorerFunction;
} {
  let cachedSeed: MasterSeed | null = null;

  return {
     
    load: async (): Promise<LoadResult<MasterSeed>> => {
      if (cachedSeed !== null) {
        return { exists: true, seed: cachedSeed };
      }
      return { exists: false };
    },

     
    store: async (seed: MasterSeed): Promise<StoreResult> => {
      cachedSeed = seed;
      return { success: true };
    },
  };
}

/**
 * Domain separator for master seed generation.
 * @internal
 */
const MASTER_SEED_DOMAIN = new TextEncoder().encode("Umbra Privacy - MasterSeedGeneration");

/**
 * Fixed personalization for master seed generation.
 *
 * Uses "seed" as the network slot because no client exists yet at this point
 * (the seed is what creates the client). Network isolation is applied in
 * subsequent derivations that have access to the client.
 * @internal
 */
const SEED_PERSONALIZATION = new TextEncoder().encode("umbra/1.0.0|kmac256/1.0.0|kdf/1.0.0|seed");

/**
 * Gets default master seed generator.
 *
 * @remarks
 * Default generation process:
 * 1. Signs the full `UMBRA_MESSAGE_TO_SIGN` consent message with the user's wallet
 * 2. Hashes the signature with KMAC256 (dkLen=64) to produce 512-bit seed
 *
 * The consent message is protocol-wide and must not be changed without a protocol
 * upgrade, since all derived keys depend on the exact message bytes.
 *
 * @param signer - The signer to use for seed generation
 * @returns Master seed generator function
 */
export function getDefaultMasterSeedGenerator(signer: IUmbraSigner): MasterSeedGeneratorFunction {
  return async (): Promise<MasterSeed> => {
    const messageBytes = new TextEncoder().encode(UMBRA_MESSAGE_TO_SIGN);

    // Sign the message
    const signature = await signer.signMessage(messageBytes);

    // Hash signature with KMAC256 to produce 64-byte seed
    const seed = defaultKmac256(
      MASTER_SEED_DOMAIN, // key (domain separator)
      signature.signature, // message (wallet signature)
      { dkLen: 64, personalization: SEED_PERSONALIZATION }, // 64 bytes = 512 bits
    );

    // Validate and return
    assertMasterSeed(seed);
    return seed;
  };
}

/* =============================================================================
 * DEFAULT NO-OP KEY STORAGE
 * ============================================================================= */

/**
 * Gets default no-op loader for a key type.
 *
 * @remarks
 * Always returns { exists: false }, forcing fresh derivation each time.
 * This is the default behavior - keys are not cached unless user provides
 * custom storage implementation.
 *
 * @template T - The type of key being loaded
 * @returns Loader function that always returns "not found"
 */
export function getDefaultKeyLoader<T>(): (...args: unknown[]) => Promise<LoadResult<T>> {
   
  return async (): Promise<LoadResult<T>> => {
    return { exists: false };
  };
}

/**
 * Gets default no-op storer for a key type.
 *
 * @remarks
 * Returns { success: true } but doesn't actually store anything.
 * This is the default behavior - keys are derived fresh each time.
 *
 * @returns Storer function that accepts any arguments and returns success
 */
export function getDefaultKeyStorer(): (...args: unknown[]) => Promise<StoreResult> {
   
  return async (): Promise<StoreResult> => {
    return { success: true };
  };
}
