/**
 * Rotate Mint X25519 Encryption Key Implementation
 *
 * This module provides the factory function for rotating the X25519 encryption
 * key on a shared-mode encrypted token account. It calls the on-chain
 * `reencrypt_shared_balance_v11` instruction which queues an Arcium MPC
 * computation to re-encrypt the balance under a new X25519 key.
 *
 * @remarks
 * ## What Is Key Rotation?
 *
 * Each shared-mode `EncryptedTokenAccount` stores an encrypted balance
 * protected by the user's X25519 public key. Over time, users may wish to
 * change which X25519 key is used for a specific mint — for example:
 *
 * - **Key compromise recovery**: The old X25519 private key may have been
 *   exposed; rotation ensures the new key secures future balances.
 * - **Key hygiene**: Periodic rotation limits the window of exposure if a key
 *   is ever compromised in the future.
 * - **Offset-based key derivation**: Umbra derives per-mint X25519 keys
 *   deterministically from the master seed and a `U256` offset. Rotation moves
 *   to a new offset, producing a fresh key pair without changing the master seed.
 *
 * ## Offset-Based Key Derivation
 *
 * The new X25519 keypair is not provided directly by the caller; instead, the
 * caller provides a `newOffset` (a 256-bit value) which is fed into the
 * `getMintX25519KeypairDeriver` function. This generator derives:
 * - An Ed25519 keypair (seed + public key)
 * - The corresponding X25519 keypair (private + public key)
 *
 * The Ed25519 keypair is used as an `x25519ProvingSigner` in the transaction
 * to cryptographically prove to the on-chain program that the caller knows the
 * new private key corresponding to the new X25519 public key they are claiming.
 * This prevents an attacker from substituting an X25519 key they do not control.
 *
 * ## Prerequisites for Key Rotation
 *
 * The token account must satisfy all three conditions (checked via status bits
 * before building the transaction):
 *
 * - **Bit 0** (`IS_INITIALISED`): The account must be initialised.
 * - **Bit 3** (`IS_SHARED_MODE`): The account must be in shared mode. MXE-mode
 *   accounts cannot have their X25519 key rotated because they do not have one.
 * - **Bit 4** (`IS_ARCIUM_BALANCE_INITIALISED`): An encrypted balance must
 *   exist to be re-encrypted under the new key.
 *
 * If any condition fails, the function throws an `Error` describing the issue
 * rather than submitting a transaction that would fail on-chain.
 *
 * ## Dual-Instruction MPC Pattern
 *
 * This function submits the **handler** transaction which queues an Arcium MPC
 * computation (`reencrypt_shared_balance_v11`). The MPC callback —
 * handled asynchronously by the Arcium network — re-encrypts the balance under
 * the new X25519 key and updates the `x25519_public_key` stored in the token
 * account.
 *
 * The function returns the handler transaction signature without waiting for the
 * MPC callback.
 *
 * ## Compute Budget
 *
 * A `SetComputeUnitLimit(1_200_000)` instruction is prepended because the
 * on-chain handler performs Ed25519 signature verification (via the
 * `x25519ProvingSigner` account), which is computationally expensive.
 *
 * ## Address Lookup Tables
 *
 * When an ALT entry for `"reencrypt_shared_balance_v11"` is present
 * in the network config, the transaction is compressed using that table to
 * stay within the 1232-byte Solana transaction size limit.
 *
 * ## Status Bit Reference
 *
 * From the Rust on-chain definition:
 * - Bit 0: `is_initialised`
 * - Bit 3: `is_shared_mode` (TRUE = Shared, FALSE = MXE)
 * - Bit 4: `is_arcium_balance_initialised`
 *
 * @packageDocumentation
 * @module implementation/umbra/services/conversion/rotate-mint-x25519-encryption-key
 */

import {
  createNoopSigner,
  createKeyPairSignerFromPrivateKeyBytes,
  appendTransactionMessageInstructions,
  compressTransactionMessageUsingAddressLookupTables,
  partiallySignTransactionMessageWithSigners,
  createTransactionMessage,
  pipe,
  setTransactionMessageFeePayer,
  setTransactionMessageLifetimeUsingBlockhash,
  type Address,
  type Instruction,
  type MaybeEncodedAccount,
} from "@solana/kit";
import { buildAltAddressesRecord, lookupAltEntry } from "../../../solana/alt-utils";
import { extractClusterOffsetFromMxeAccount } from "../../../common/arcium";
import { createSetComputeUnitLimitInstruction } from "../../../solana/constants";
import {
  getReencryptSharedBalanceV11InstructionAsync,
  decodeEncryptedTokenAccount,
} from "@umbra-privacy/umbra-codama";
import type {
  RotateMintX25519EncryptionKeyFunction as RotateMintX25519EncryptionKeyFunction,
  GetRotateMintX25519EncryptionKeyFunctionArgs as GetRotateMintX25519EncryptionKeyFunctionArgs,
  GetRotateMintX25519EncryptionKeyFunctionDeps as GetRotateMintX25519EncryptionKeyFunctionDeps,
  SignableTransaction,
  TransactionCallbacks,
} from "../../interfaces";
import type { MicroLamportsPerAcu } from "../../../types/arcium";
import type { OptionalData32, TransactionSignature } from "../../../types";
import { findEncryptedTokenAccountPda } from "../../../common/pda/user";
import { findArciumInfrastructurePdas } from "../../../common/pda/arcium";
import { generateRandomU64, generateRandomU128 } from "../../../common/math-utils";
import { getMintX25519KeypairDeriver } from "../../../crypto/key-derivation";

/* =============================================================================
 * STATUS BIT CONSTANTS
 * ============================================================================= */

/**
 * Status bit positions for the `EncryptedTokenAccount.statusBits` field,
 * used to validate pre-flight eligibility for X25519 key rotation.
 *
 * @remarks
 * From on-chain definition:
 * - Bit 0: `is_initialised`
 * - Bit 3: `is_shared_mode` (TRUE = Shared, FALSE = MXE)
 * - Bit 4: `is_arcium_balance_initialised`
 *
 * @internal
 */
const TOKEN_ACCOUNT_STATUS_BITS = {
  IS_INITIALISED: 0,
  IS_SHARED_MODE: 3,
  IS_ARCIUM_BALANCE_INITIALISED: 4,
} as const;

/**
 * Checks if a specific bit is set in a value.
 *
 * @remarks
 * Accepts both `number` and `bigint` to handle the codama-decoded
 * `statusBits.first` type, which may be either. Uses `BigInt` arithmetic
 * throughout to avoid 32-bit integer truncation.
 *
 * @param value - The value to check (can be number or bigint).
 * @param bitPosition - The zero-indexed bit position to check.
 * @returns `true` if the bit at `bitPosition` is set; `false` otherwise.
 *
 * @internal
 */
function isBitSet(value: number | bigint, bitPosition: number): boolean {
  return (BigInt(value) & (1n << BigInt(bitPosition))) !== 0n;
}

/**
 * Default optional data: 32 zero bytes used when the caller does not supply
 * application-specific metadata.
 *
 * @internal
 */
const DEFAULT_OPTIONAL_DATA_BYTES = new Uint8Array(32);

/* =============================================================================
 * FACTORY FUNCTION
 * ============================================================================= */

/**
 * Creates a function for rotating the X25519 encryption key on a shared-mode
 * encrypted token account.
 *
 * @remarks
 * This follows the SDK factory pattern: the factory is called once during
 * client setup to capture dependencies, and the returned function is called
 * at runtime to perform the rotation. The `mintX25519KeypairDeriver` is
 * resolved at factory construction time.
 *
 * Dependency resolution order: explicit `deps` override takes precedence,
 * then the corresponding field on `client`.
 *
 * @param args - Required arguments containing the configured Umbra client.
 *   The client provides the wallet signer, blockhash provider, account info
 *   provider, transaction forwarder, and network configuration.
 * @param deps - Optional dependency overrides. When provided, each override
 *   replaces the corresponding client-level default. Particularly useful for
 *   injecting a custom `mintX25519KeypairDeriver` in tests.
 * @returns A `RotateMintX25519EncryptionKeyFunction` that, when called, fetches
 *   the token account state, validates eligibility, builds the handler
 *   transaction, signs it, and submits it on-chain.
 *
 * @example
 * ```typescript
 * import { getRotateMintX25519EncryptionKeyFunction } from "@umbra-privacy/sdk";
 * import { address } from "@solana/kit";
 *
 * // Create the rotation function (once, at client setup)
 * // The new offset is set on the client at construction time
 * const newClient = getUmbraClient({ signer, network, offsets: { mintX25519PrivateKey: 1n } });
 * const rotateKey = getRotateMintX25519EncryptionKeyFunction({ client: newClient });
 *
 * // Rotate to the new X25519 key derived from client.offsets.mintX25519PrivateKey
 * const signature = await rotateKey(
 *   address("EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v"), // USDC mint
 * );
 * console.log("Key rotation handler queued:", signature);
 * // The Arcium MPC callback will complete the re-encryption asynchronously
 * ```
 *
 * @example
 * ```typescript
 * // With optional data and lifecycle callbacks
 * const signature = await rotateKey(
 *   usdcMint,
 *   new Uint8Array(32),   // optionalData
 *   {
 *     pre: async () => console.log("Submitting key rotation handler..."),
 *     post: async ({ signature }) => console.log("Handler confirmed:", signature),
 *   },
 * );
 * ```
 *
 * @see {@link RotateMintX25519EncryptionKeyFunction} — the type of the returned function
 * @see {@link GetRotateMintX25519EncryptionKeyFunctionArgs} — factory argument type
 * @see {@link GetRotateMintX25519EncryptionKeyFunctionDeps} — injectable dependency type
 * @see {@link getConvertToSharedEncryptionFunction} — converts MXE accounts to shared mode first
 * @public
 */
export function getMintEncryptionKeyRotatorFunction(
  args: GetRotateMintX25519EncryptionKeyFunctionArgs,
  deps?: GetRotateMintX25519EncryptionKeyFunctionDeps,
): RotateMintX25519EncryptionKeyFunction {
  const { client } = args;
  const { signer } = client;

  // ========================================================================
  // DEPENDENCY RESOLUTION
  // ========================================================================

  const accountInfoProvider = deps?.rpc?.accountInfoProvider ?? client.accountInfoProvider;
  const getLatestBlockhash = deps?.rpc?.blockhashProvider ?? client.blockhashProvider;
  const transactionForwarder = deps?.rpc?.transactionForwarder ?? client.transactionForwarder;
  const mintX25519KeypairDeriver =
    deps?.keys?.mintX25519KeypairDeriver ?? getMintX25519KeypairDeriver({ client });

  // ========================================================================
  // RETURNED FUNCTION
  // ========================================================================

  /**
   * Rotates the X25519 encryption key for a shared-mode encrypted token account.
   *
   * @remarks
   * ## Pre-Flight Validation
   *
   * Before building the transaction, the function fetches the token account
   * on-chain and checks three status bits. If any check fails, an `Error` is
   * thrown immediately:
   * - Account does not exist → throws with mint address in the message.
   * - `IS_INITIALISED` is zero → throws `"not initialized"`.
   * - `IS_SHARED_MODE` is zero → throws `"in MXE mode, not shared mode"`.
   * - `IS_ARCIUM_BALANCE_INITIALISED` is zero → throws `"no initialized Arcium balance"`.
   *
   * ## Two-Signer Pattern
   *
   * This instruction requires two signatures:
   * 1. **Wallet signer** (`userAddress` / `feePayer`) — pays fees and proves
   *    wallet ownership.
   * 2. **X25519 proving signer** (`x25519ProvingSigner`) — an Ed25519 keypair
   *    derived from `(mint, newOffset)` whose X25519 public key will become the
   *    new encryption key. Its signature proves the caller knows the private key
   *    for the new X25519 key they are claiming.
   *
   * `partiallySignTransactionMessageWithSigners` handles the proving signer
   * automatically (it is a `KeyPairSigner`). The wallet signer is applied
   * afterward via `signer.signTransaction`.
   *
   * @param mint - The SPL mint address of the encrypted token account whose
   *   X25519 key should be rotated.
   * @param optionalData - An optional 32-byte payload for application-level
   *   metadata or tagging. Defaults to 32 zero bytes if not provided.
   * @param callbacks - Optional lifecycle hooks invoked before and after the
   *   handler transaction submission.
   * @returns The transaction signature of the submitted handler transaction.
   * @throws `Error` if the token account does not exist.
   * @throws `Error` if the token account is not initialised.
   * @throws `Error` if the token account is in MXE mode (not shared mode).
   * @throws `Error` if the token account has no initialised Arcium balance.
   *
   * @example
   * ```typescript
   * const sig = await rotateMintX25519EncryptionKey(usdcMint);
   * ```
   *
   * @param options - Optional. Pass `{ accountInfoCommitment }` to override the
   *   default `"confirmed"` commitment level for account reads.
   * @public
   */
  return async function rotateMintX25519EncryptionKey(
    mint: Address,
    optionalData?: OptionalData32,
    callbacks?: TransactionCallbacks,
    microLamportsPerAcu?: MicroLamportsPerAcu,
    options?: { readonly accountInfoCommitment?: "processed" | "confirmed" | "finalized" },
  ): Promise<TransactionSignature> {
    const accountInfoCommitment = options?.accountInfoCommitment ?? "confirmed";
    const userAddress = signer.address;

    // ================================================================
    // Step 1: Derive new X25519 keypair from mint using client.offsets.mintX25519PrivateKey
    // ================================================================

    const keypairResult = await mintX25519KeypairDeriver(mint);

    // Create KeyPairSigner from Ed25519 seed for the x25519ProvingSigner account
    const x25519ProvingSigner = await createKeyPairSignerFromPrivateKeyBytes(
      keypairResult.ed25519Keypair.seed,
    );

    // ================================================================
    // Step 2: Pre-flight validation — fetch and check token account
    // ================================================================

    const tokenAccountPda = await findEncryptedTokenAccountPda(
      userAddress,
      mint,
      client.networkConfig.programId,
    );

    const accountMap = await accountInfoProvider([client.networkConfig.mxeAccountAddress, tokenAccountPda], { commitment: accountInfoCommitment });

    const clusterOffset = extractClusterOffsetFromMxeAccount(
      accountMap.get(client.networkConfig.mxeAccountAddress)!,
    );

    const maybeAccount: MaybeEncodedAccount<Address> | undefined = accountMap.get(tokenAccountPda);

    if (maybeAccount?.exists !== true) {
      throw new Error(
        `Token account for mint ${mint} does not exist. ` +
          `Cannot rotate X25519 key on a non-existent account.`,
      );
    }

    const decodedAccount = decodeEncryptedTokenAccount(
      maybeAccount as MaybeEncodedAccount<Address> & { exists: true },
    );
    const statusBits = decodedAccount.data.statusBits.first;

    const isInitialised = isBitSet(statusBits, TOKEN_ACCOUNT_STATUS_BITS.IS_INITIALISED);
    const isSharedMode = isBitSet(statusBits, TOKEN_ACCOUNT_STATUS_BITS.IS_SHARED_MODE);
    const isArciumBalanceInitialised = isBitSet(
      statusBits,
      TOKEN_ACCOUNT_STATUS_BITS.IS_ARCIUM_BALANCE_INITIALISED,
    );

    if (!isInitialised) {
      throw new Error(
        `Token account for mint ${mint} is not initialized. ` +
          `Cannot rotate X25519 key on an uninitialized account.`,
      );
    }

    if (!isSharedMode) {
      throw new Error(
        `Token account for mint ${mint} is in MXE mode, not shared mode. ` +
          `X25519 key rotation requires the account to be in shared mode.`,
      );
    }

    if (!isArciumBalanceInitialised) {
      throw new Error(
        `Token account for mint ${mint} has no initialized Arcium balance. ` +
          `Cannot rotate X25519 key on an account without initialized balance.`,
      );
    }

    // ================================================================
    // Step 3: Generate random offsets and derive Arcium accounts
    // ================================================================

    const computationOffset = generateRandomU64();
    const mpcCallbackDataOffset = generateRandomU128();

    const arciumAccounts = await findArciumInfrastructurePdas(
      client.networkConfig.programId,
      client.networkConfig.arciumProgramAddress,
      clusterOffset,
      BigInt(computationOffset),
      "reencrypt_shared_balance_v11",
    );

    // ================================================================
    // Step 4: Build the instruction
    // ================================================================

    const noopSigner = createNoopSigner(userAddress);
    const instruction: Instruction = await getReencryptSharedBalanceV11InstructionAsync({
      // Signers (noop for instruction building — wallet signs later)
      userAddress: noopSigner,
      feePayer: noopSigner,
      // Arcium accounts
      mxeAccount: arciumAccounts.mxeAccount,
      mempoolAccount: arciumAccounts.mempoolAccount,
      executingPool: arciumAccounts.executingPoolAccount,
      computationAccount: arciumAccounts.computationAccount,
      compDefAccount: arciumAccounts.compDefAccount,
      clusterAccount: arciumAccounts.clusterAccount,
      // Token mint
      mint,
      // X25519 proving signer (KeyPairSigner — auto-signed by partiallySign)
      x25519ProvingSigner,
      // Instruction data
      computationOffset: {
        first: computationOffset,
      },
      mpcCallbackDataOffset: {
        first: mpcCallbackDataOffset,
      },
      priorityFees: { first: microLamportsPerAcu ?? 0n },
      optionalData: { first: optionalData ?? DEFAULT_OPTIONAL_DATA_BYTES },
    }, { programAddress: client.networkConfig.programId });

    // ================================================================
    // Step 5: Build, sign, and forward the transaction
    // ================================================================

    const latestBlockhash = await getLatestBlockhash();

    const computeBudgetInstruction = createSetComputeUnitLimitInstruction(1_200_000);

    const baseTransactionMessage = pipe(
      createTransactionMessage({ version: 0 }),
      (m) => setTransactionMessageFeePayer(userAddress, m),
      (m) => setTransactionMessageLifetimeUsingBlockhash(latestBlockhash, m),
      (m) => appendTransactionMessageInstructions([computeBudgetInstruction, instruction], m),
    );

    // Compress with Address Lookup Table (if available)
    const altEntry = lookupAltEntry(client.networkConfig.addressLookupTables, clusterOffset, "reencrypt_shared_balance_v11");

    const transactionMessage =
      altEntry === undefined
        ? baseTransactionMessage
        : compressTransactionMessageUsingAddressLookupTables(
            baseTransactionMessage,
            buildAltAddressesRecord(altEntry),
          );

    // Partially sign — x25519ProvingSigner (KeyPairSigner) is auto-signed,
    // wallet signer slot remains null for the next step
    const partiallySignedTransaction =
      await partiallySignTransactionMessageWithSigners(transactionMessage);

    // Sign with wallet signer
    const signedTransaction = await signer.signTransaction(
      partiallySignedTransaction as SignableTransaction,
    );

    // Forward the transaction
    await callbacks?.pre?.(signedTransaction);
    const signatures = await transactionForwarder.forwardInParallel([signedTransaction]);
    const signature = signatures[0];
    await callbacks?.post?.(signedTransaction, signature);
    return signature;
  };
}
