/* =============================================================================
 * INTERNAL ASSERTION HELPERS
 * ============================================================================= */

/**
 * Asserts that the given client object is non-null and non-undefined.
 *
 * @remarks
 * This is a lightweight guard that runs at factory construction time, before
 * any closures are captured. It ensures that subsequent accesses to `client.signer`,
 * `client.networkConfig`, etc. do not throw opaque `Cannot read property of null`
 * errors. More detailed validation (e.g., checking that `signer.address` is a
 * valid base-58 string) is handled by {@link assertValidSigner}.
 *
 * @param client - The Umbra client instance to validate
 * @throws {EncryptedWithdrawalError} With stage `"initialization"` if `client` is
 *   `null` or `undefined`
 *
 * @see {@link IUmbraClient}
 * @internal
 */
function assertValidClient(client: IUmbraClient): void {
   
  if (client === undefined || client === null) {
    throw new EncryptedWithdrawalError("initialization", "client is required");
  }
}

/**
 * Asserts that the given signer object is fully configured for signing transactions.
 *
 * @remarks
 * Validates three properties on the signer:
 * 1. The signer is not null or undefined.
 * 2. `signer.address` is a non-empty string (expected to be a base-58 Solana pubkey).
 * 3. `signer.signTransaction` is a callable function.
 *
 * This validation runs at factory construction time so that any misconfiguration
 * is caught immediately rather than at the moment of the first withdrawal attempt.
 *
 * @param signer - The `IUmbraSigner` object from `client.signer`
 * @throws {EncryptedWithdrawalError} With stage `"initialization"` if any signer
 *   property is missing or has an unexpected type
 *
 * @see {@link IUmbraSigner}
 * @internal
 */
function assertValidSigner(signer: IUmbraSigner): void {
   
  if (signer === undefined || signer === null) {
    throw new EncryptedWithdrawalError("initialization", "client.signer is required");
  }

  if (typeof signer.address !== "string" || signer.address.trim().length === 0) {
    throw new EncryptedWithdrawalError(
      "initialization",
      "client.signer.address must be a non-empty string",
    );
  }

  if (typeof signer.signTransaction !== "function") {
    throw new EncryptedWithdrawalError(
      "initialization",
      "client.signer.signTransaction must be a function",
    );
  }
}

/**
 * Asserts that the given blockhash provider is a callable function.
 *
 * @remarks
 * The blockhash provider is called once per transaction to obtain a recent
 * blockhash that sets the transaction's lifetime window. This guard ensures
 * the provider is properly set before any withdrawal attempt.
 *
 * @param provider - The `GetLatestBlockhash` function (or dependency override)
 * @throws {EncryptedWithdrawalError} With stage `"initialization"` if `provider`
 *   is not a function
 *
 * @see {@link GetLatestBlockhash}
 * @internal
 */
function assertValidBlockhashProvider(provider: GetLatestBlockhash): void {
  if (typeof provider !== "function") {
    throw new EncryptedWithdrawalError("initialization", "getLatestBlockhash must be a function");
  }
}

/**
 * Asserts that the given transaction forwarder is a valid object with a
 * `forwardSequentially` method.
 *
 * @remarks
 * The transaction forwarder is responsible for submitting signed transactions to
 * the Solana network and waiting for confirmation. It must expose a
 * `forwardSequentially` method that accepts an array of signed transactions and
 * returns an array of base-58 signatures.
 *
 * @param forwarder - The `TransactionForwarder` instance (or dependency override)
 * @throws {EncryptedWithdrawalError} With stage `"initialization"` if `forwarder`
 *   is null/undefined or its `forwardSequentially` property is not a function
 *
 * @see {@link TransactionForwarder}
 * @internal
 */
function assertValidTransactionForwarder(forwarder: TransactionForwarder): void {
   
  if (forwarder === undefined || forwarder === null) {
    throw new EncryptedWithdrawalError("initialization", "transactionForwarder is required");
  }

  if (typeof forwarder.forwardSequentially !== "function") {
    throw new EncryptedWithdrawalError(
      "initialization",
      "transactionForwarder.forwardSequentially must be a function",
    );
  }
}

/**
 * Asserts that a value is a non-empty string and narrows its type to `Address`.
 *
 * @remarks
 * Used in the per-invocation validation step to check `destinationAddress` and
 * `mint` before making any RPC calls. The `name` parameter is included in the
 * error message so callers can identify which address field failed.
 *
 * @param address - The value to test (typed as `unknown` to allow use before type narrowing)
 * @param name - Human-readable field name for the error message (e.g., `"destinationAddress"`)
 * @throws {EncryptedWithdrawalError} With stage `"validation"` if `address` is not
 *   a non-empty string
 *
 * @internal
 */
function assertValidAddress(address: unknown, name: string): asserts address is Address {
  if (typeof address !== "string" || address.trim().length === 0) {
    throw new EncryptedWithdrawalError("validation", `Invalid ${name}: must be a non-empty string`);
  }
}

/**
 * Asserts that all six required Arcium PDA accounts have been successfully derived.
 *
 * @remarks
 * `findArciumInfrastructurePdas` returns an object with six address fields. This
 * guard checks that each field is a non-empty string, catching any PDA derivation
 * failure that returned an empty string rather than throwing.
 *
 * The six required accounts are:
 * - `mxeAccount`: The Arcium MXE (Multi-Party Execution environment) account
 * - `mempoolAccount`: The computation mempool account
 * - `executingPoolAccount`: The pool executing the computation
 * - `computationAccount`: The per-computation PDA storing inputs and outputs
 * - `compDefAccount`: The computation definition PDA (identifies the MPC program)
 * - `clusterAccount`: The Arcium cluster account authorizing the callback
 *
 * @param accounts - The return value of `findArciumInfrastructurePdas`
 * @throws {EncryptedWithdrawalError} With stage `"pda-derivation"` if any of the
 *   six account addresses is missing or empty
 *
 * @internal
 */
function assertValidArciumAccounts(
  accounts: Awaited<ReturnType<typeof findArciumInfrastructurePdas>>,
): void {
  const requiredAccounts = [
    "mxeAccount",
    "mempoolAccount",
    "executingPoolAccount",
    "computationAccount",
    "compDefAccount",
    "clusterAccount",
  ] as const;

  for (const accountName of requiredAccounts) {
    const account = accounts[accountName];
    if (typeof account !== "string" || account.trim().length === 0) {
      throw new EncryptedWithdrawalError(
        "pda-derivation",
        `Failed to derive ${accountName}: account address is invalid`,
      );
    }
  }
}

/* =============================================================================
 * FACTORY FUNCTION
 * ============================================================================= */

/**
 * Creates an ETA-to-ATA withdrawal function bound to the given Umbra client.
 *
 * @remarks
 * This factory implements the "direct withdrawal" path in Umbra: tokens move from
 * the user's Encrypted Token Account (ETA) to any public Associated Token Account
 * (ATA) via the Arcium MPC network. The factory pattern separates one-time
 * dependency setup from repeated invocations of the withdrawal itself.
 *
 * **Factory Pattern:**
 * Calling `getEncryptedBalanceToPublicBalanceDirectWithdrawerFunction(args, deps)` immediately
 * validates all dependencies and captures them in a closure. The returned function
 * (`withdrawIntoPublicBalance`) can then be called multiple times — once per
 * withdrawal — without repeating setup work.
 *
 * **The "V4" Instruction:**
 * The `V4` suffix refers to `withdraw_from_shared_balance_into_public_balance_v11`, the fourth revision
 * of this instruction in the Umbra program. V4 uses the current Arcium account
 * layout with `mpcCallbackDataOffset` for callback data PDA derivation, and the
 * unified `feeVaultOffset` field for the fee configuration. This field
 * is currently hardcoded to `0n` (the default offset), matching the on-chain
 * program's expected default state.
 *
 * **MPC Computation Flow:**
 * The handler instruction queued by this factory:
 * 1. Validates the user's ETA exists and is active.
 * 2. Stores withdrawal parameters in a `MpcCallbackData` PDA keyed by
 *    `mpcCallbackDataOffset`.
 * 3. Queues a decryption computation on the Arcium network via the mempool.
 *
 * The Arcium network's callback (not invoked here):
 * 1. Decrypts the user's encrypted balance using the MPC network's secret shares.
 * 2. Verifies `encryptedBalance >= withdrawalAmount + protocolFees`.
 * 3. Updates the encrypted balance to `encryptedBalance - withdrawalAmount - fees`.
 * 4. Transfers `withdrawalAmount` tokens from the program vault to the destination ATA.
 * 5. Transfers protocol fees to the unified fees pool.
 *
 * **ALT (Address Lookup Table):**
 * The withdrawal instruction references many Arcium accounts. The single ALT entry
 * `withdraw_from_shared_balance_into_public_balance_v11` in `client.networkConfig.addressLookupTables`
 * compresses these accounts into index references, keeping the transaction within
 * Solana's 1232-byte size limit.
 *
 * **Computation Offsets:**
 * - `computationOffset` (u64): A randomly generated value that seeds the PDA
 *   derivation for the per-computation account. It uniquely identifies this MPC
 *   computation instance, preventing replay or collision with concurrent operations.
 * - `mpcCallbackDataOffset` (u128): A randomly generated value that seeds the
 *   `MpcCallbackData` PDA, which stores the callback parameters until Arcium
 *   executes the decryption and calls back.
 *
 * @param args - Required configuration. Must contain an initialized `IUmbraClient`
 *   with `signer`, `accountInfoProvider`, `blockhashProvider`, `transactionForwarder`,
 *   and `networkConfig` all properly set.
 * @param deps - Optional dependency overrides for testing or custom deployments.
 *   When omitted, all values default to the client's own providers.
 * @returns A {@link EncryptedBalanceToPublicBalanceDirectWithdrawerFunction} that, when called,
 *   executes the full withdrawal pipeline and returns the transaction signature.
 *
 * @throws {EncryptedWithdrawalError} With stage `"initialization"` during factory
 *   construction if the client, signer, blockhash provider, or transaction forwarder
 *   is missing or misconfigured.
 * @throws {EncryptedWithdrawalError} During execution of the returned function, with
 *   a discriminated `stage` field:
 *   - `"validation"`: Invalid inputs (address, amount, optionalData)
 *   - `"mint-fetch"`: Mint account not found or unknown token program
 *   - `"pda-derivation"`: Arcium account PDA derivation failed
 *   - `"instruction-build"`: Codama instruction builder failed or returned null
 *   - `"transaction-build"`: Blockhash fetch or message construction failed
 *   - `"transaction-compile"`: Partial signing / compilation failed
 *   - `"transaction-sign"`: Wallet signer rejected or returned null
 *   - `"transaction-send"`: Network rejected the transaction or forwarder timed out
 *
 * @example
 * Basic usage with defaults:
 * ```typescript
 * import { getEncryptedBalanceToPublicBalanceDirectWithdrawerFunction } from '@umbra-privacy/sdk';
 *
 * const withdraw = getEncryptedBalanceToPublicBalanceDirectWithdrawerFunction({ client });
 *
 * // Withdraw to self with all defaults
 * const signature = await withdraw(
 *   client.signer.address,
 *   usdcMint,
 *   1000n as U64
 * );
 * ```
 *
 * @example
 * Withdraw to another address:
 * ```typescript
 * const signature = await withdraw(
 *   recipientAddress,
 *   usdcMint,
 *   500n as U64,
 *   { priorityFees: 10000n as U64 }
 * );
 * ```
 *
 * @example
 * With all options:
 * ```typescript
 * const signature = await withdraw(
 *   recipientAddress,
 *   usdcMint,
 *   500n as U64,
 *   {
 *     priorityFees: 10000n as U64,
 *     optionalData: myOptionalData
 *   }
 * );
 * ```
 *
 * @example
 * With custom dependencies:
 * ```typescript
 * const withdraw = getEncryptedBalanceToPublicBalanceDirectWithdrawerFunction(
 *   { client },
 *   {
 *     getLatestBlockhash: myCustomBlockhashProvider,
 *     transactionForwarder: myCustomForwarder,
 *   }
 * );
 * ```
 *
 * @see {@link EncryptedBalanceToPublicBalanceDirectWithdrawerFunction} - The type of the returned function
 * @see {@link EncryptedBalanceToPublicBalanceDirectWithdrawerOptions} - Options accepted by the returned function
 * @see {@link findArciumInfrastructurePdas} - PDA derivation for Arcium accounts
 *
 * @public
 */
export function getEncryptedBalanceToPublicBalanceDirectWithdrawerFunction(
  args: GetEncryptedBalanceToPublicBalanceDirectWithdrawerFunctionArgs,
  deps?: GetEncryptedBalanceToPublicBalanceDirectWithdrawerFunctionDeps,
): EncryptedBalanceToPublicBalanceDirectWithdrawerFunction {
  // ========================================================================
  // FACTORY-LEVEL VALIDATION
  // ========================================================================

  const { client } = args;

  // Validate client
  assertValidClient(client);

  // Validate signer
  const { signer } = client;
  assertValidSigner(signer);

  // ========================================================================
  // SOLANA/RPC DEPENDENCIES
  // ========================================================================

  const accountInfoProvider = deps?.rpc?.accountInfoProvider ?? client.accountInfoProvider;

  const getLatestBlockhash = deps?.rpc?.blockhashProvider ?? client.blockhashProvider;

  const transactionForwarder = deps?.rpc?.transactionForwarder ?? client.transactionForwarder;

  // Validate dependencies
  assertValidBlockhashProvider(getLatestBlockhash);
  assertValidTransactionForwarder(transactionForwarder);

  // Factory-level behaviour config
  const factoryMicroLamportsPerAcu = deps?.arcium?.microLamportsPerAcu ?? (0n as MicroLamportsPerAcu);
  const factoryAwaitComputationFinalization = deps?.arcium?.awaitComputationFinalization;

  // ========================================================================
  // HELPER: Execute a single transaction
  // ========================================================================

  /**
   * Assembles, signs, and submits a single Solana transaction containing
   * the withdrawal instruction. Applies the ALT for the `withdraw_from_shared_balance_into_public_balance_v11`
   * instruction if one is configured in the network config.
   *
   * @remarks
   * The transaction lifecycle is:
   * 1. Fetch and validate the latest blockhash.
   * 2. Construct a versioned (v0) transaction message with the fee payer, blockhash,
   *    and the single withdrawal instruction.
   * 3. Attempt to compress the transaction using the `withdraw_from_shared_balance_into_public_balance_v11`
   *    ALT entry from `client.networkConfig.addressLookupTables`. If no ALT is
   *    configured for this instruction, the transaction is sent uncompressed.
   * 4. Partially sign the compiled transaction — `NoopSigner`s contribute nothing;
   *    they are placeholders for the wallet signer in step 5.
   * 5. Have the wallet signer sign the transaction.
   * 6. Validate the signed transaction is non-null.
   * 7. Forward (submit and confirm) the signed transaction.
   * 8. Validate the returned signature and return it.
   *
   * Unlike the deposit's `executeTransaction`, this helper does not accept an `altEntry`
   * parameter — it reads the ALT directly from `client.networkConfig.addressLookupTables`
   * using the fixed key `withdraw_from_shared_balance_into_public_balance_v11`.
   *
   * @param instruction - The single Solana withdrawal instruction to execute
   * @returns The base-58 encoded transaction signature after confirmation
   *
   * @throws {EncryptedWithdrawalError} With stage `"transaction-build"` if the
   *   blockhash is invalid or message construction fails
   * @throws {EncryptedWithdrawalError} With stage `"transaction-compile"` if
   *   partial signing / compilation fails
   * @throws {EncryptedWithdrawalError} With stage `"transaction-sign"` if the
   *   wallet signer rejects or returns null
   * @throws {EncryptedWithdrawalError} With stage `"transaction-send"` if the
   *   forwarder throws or returns an invalid signature
   *
   * @internal
   */
  // Create the shared transaction executor configuration
  const executorConfig: TransactionExecutorConfig = {
    signer,
    getLatestBlockhash,
    transactionForwarder,
    computationMonitor: client.computationMonitor,
  };

  async function executeTransaction(
    instruction: Instruction,
    fetchedClusterOffset: number,
    awaitCallback?: AwaitCallbackOptions,
  ): Promise<WithdrawResult> {
    // Look up the ALT entry for this instruction
    const altEntry = lookupAltEntry(client.networkConfig.addressLookupTables, fetchedClusterOffset, "withdraw_from_shared_balance_into_public_balance_v11");

    // Build, sign, forward, and optionally monitor using the shared utility
    try {
      const result = await executeComputationTransaction(
        executorConfig,
        {
          instruction,
          preInstructions: [createSetComputeUnitLimitInstruction(400_000)],
          altEntry,
        },
        awaitCallback,
      );
      if ("callbackResult" in result) {
        return {
          queueSignature: result.signature,
          callbackStatus: result.callbackResult.status,
          callbackSignature:
            "callbackSignature" in result.callbackResult
              ? result.callbackResult.callbackSignature
              : undefined,
          callbackElapsedMs: result.callbackResult.elapsedMs,
          rentClaimSignature: result.rentClaimSignature,
          rentClaimError: result.rentClaimError,
        };
      }
      return { queueSignature: result.signature };
    } catch (error) {
      if (error instanceof EncryptedWithdrawalError) {
        throw error;
      }
      throw new EncryptedWithdrawalError(
        "transaction-send",
        `Transaction execution failed: ${error instanceof Error ? error.message : String(error)}`,
        error instanceof Error ? error : undefined,
      );
    }
  }

  // ========================================================================
  // RETURN THE WITHDRAWAL FUNCTION
  // ========================================================================

  /**
   * Executes a direct ETA-to-ATA token withdrawal for a given destination and mint.
   *
   * @remarks
   * This function performs the full withdrawal pipeline:
   * 1. Validate and normalize all input parameters.
   * 2. Fetch the mint account to determine the token program (SPL Token vs Token-2022).
   *    This is needed to pass the correct `tokenProgram` account to the Arcium
   *    callback so it uses the right program when transferring tokens to the ATA.
   * 3. Generate a random `computationOffset` and `mpcCallbackDataOffset`.
   * 4. Derive all required Arcium PDA addresses and validate them.
   * 5. Build the `withdraw_from_shared_balance_into_public_balance_v11` instruction via the
   *    Codama-generated async builder.
   * 6. Validate the built instruction is non-null.
   * 7. Execute and return the transaction signature.
   *
   * **Note on withdrawal amount:** The `withdrawalAmount` is the gross amount
   * requested. The Arcium network's callback will deduct protocol fees from this
   * amount before transferring to the ATA. The net amount received by the ATA
   * will therefore be `withdrawalAmount - protocolFees`. There is no client-side
   * fee calculation in this module (unlike the deposit path for Token-2022 fees).
   *
   * @param destinationAddress - The Solana address of the ATA that will receive
   *   the withdrawn tokens. This must be an existing, valid SPL token account for
   *   the specified `mint`. It can be the signer's own address or any other address.
   * @param mint - The SPL token or Token-2022 mint address for the token being
   *   withdrawn from the ETA.
   * @param withdrawalAmount - The number of tokens (in base units, as a u64 bigint)
   *   to withdraw from the ETA. Must be greater than zero. The full amount (before
   *   protocol fee deduction) is passed to the on-chain instruction.
   * @param options - Optional configuration overrides.
   * @param options.priorityFees - Compute unit price in lamports. Defaults to `0n`.
   * @param options.optionalData - 32-byte application metadata blob. Defaults to
   *   32 zero bytes.
   * @returns A promise that resolves to the base-58 encoded transaction signature
   *   of the confirmed handler transaction. Note: this signature represents the
   *   handler instruction only. The actual balance update and token transfer occur
   *   when the Arcium network executes the callback (a separate transaction).
   *
   * @throws {EncryptedWithdrawalError} With stage `"validation"` for invalid inputs.
   * @throws {EncryptedWithdrawalError} With stage `"mint-fetch"` if the mint account
   *   cannot be read or belongs to an unknown token program.
   * @throws {EncryptedWithdrawalError} With stage `"pda-derivation"` if Arcium account
   *   derivation fails or any derived address is empty.
   * @throws {EncryptedWithdrawalError} With stage `"instruction-build"` if the
   *   Codama-generated instruction builder fails or returns null.
   * @throws {EncryptedWithdrawalError} From `executeTransaction` for transaction-level
   *   failures (blockhash, compilation, signing, submission).
   */
  return async function withdrawIntoPublicBalance(
    destinationAddress: Address,
    mint: Address,
    withdrawalAmount: U64,
    options?: EncryptedBalanceToPublicBalanceDirectWithdrawerOptions,
  ): Promise<WithdrawResult> {
    const accountInfoCommitment = options?.accountInfoCommitment ?? "confirmed";
    // ================================================================
    // Step 1: Extract options with defaults
    // ================================================================

    const microLamportsPerAcu = factoryMicroLamportsPerAcu;
    const optionalData = options?.optionalData ?? new Uint8Array(32);

    // ================================================================
    // Step 2: Validate input parameters using assertions
    // ================================================================

    try {
      // Validate destination address
      assertValidAddress(destinationAddress, "destinationAddress");

      // Validate mint address
      assertValidAddress(mint, "mint");

      // Validate withdrawalAmount using branded type assertion
      assertU64(withdrawalAmount);
      if (withdrawalAmount <= 0n) {
        throw new EncryptedWithdrawalError(
          "validation",
          "Invalid withdrawalAmount: must be greater than zero",
        );
      }

      // Validate optionalData using branded type assertion
      assertOptionalData32(optionalData, "optionalData");
    } catch (error) {
      // Re-throw EncryptedWithdrawalError as-is
      if (error instanceof EncryptedWithdrawalError) {
        throw error;
      }
      // Wrap assertion errors in EncryptedWithdrawalError
      throw new EncryptedWithdrawalError(
        "validation",
        error instanceof Error ? error.message : String(error),
        error instanceof Error ? error : undefined,
      );
    }

    // ================================================================
    // Step 3: Detect mint's token program
    // ================================================================

    let mintTokenProgram: Address;
    let clusterOffset: number;
    try {
      const mintAccountMap = await accountInfoProvider([mint, client.networkConfig.mxeAccountAddress], { commitment: accountInfoCommitment });
      const mintAccount = mintAccountMap.get(mint);

      if (mintAccount?.exists !== true) {
        throw new EncryptedWithdrawalError("mint-fetch", `Mint account not found: ${mint}`);
      }

      const mintOwner = mintAccount.programAddress;

      if (mintOwner !== SPL_TOKEN_PROGRAM_ID && mintOwner !== TOKEN_2022_PROGRAM_ID) {
        throw new EncryptedWithdrawalError(
          "mint-fetch",
          `Unknown token program: ${mintOwner}. Expected SPL Token (${SPL_TOKEN_PROGRAM_ID}) or Token-2022 (${TOKEN_2022_PROGRAM_ID})`,
        );
      }

      mintTokenProgram = mintOwner;

      // Extract cluster offset from MXE account (fetched in the same batch)
      clusterOffset = extractClusterOffsetFromMxeAccount(
        mintAccountMap.get(client.networkConfig.mxeAccountAddress)!,
      );
    } catch (error) {
      if (error instanceof EncryptedWithdrawalError) {
        throw error;
      }
      throw new EncryptedWithdrawalError(
        "mint-fetch",
        `Failed to fetch mint account: ${error instanceof Error ? error.message : String(error)}`,
        error instanceof Error ? error : undefined,
      );
    }

    // ================================================================
    // Step 4: Generate computation offset and get Arcium accounts
    // ================================================================

    const computationOffset = generateRandomU64();

    // Get Arcium account addresses for the computation
    let arciumAccounts: Awaited<ReturnType<typeof findArciumInfrastructurePdas>>;
    try {
      arciumAccounts = await findArciumInfrastructurePdas(
        client.networkConfig.programId,
        client.networkConfig.arciumProgramAddress,
        clusterOffset,
        BigInt(computationOffset),
        "withdraw_from_shared_balance_into_public_balance_v11",
      );
    } catch (error) {
      throw new EncryptedWithdrawalError(
        "pda-derivation",
        `Failed to get Arcium account addresses: ${error instanceof Error ? error.message : String(error)}`,
        error instanceof Error ? error : undefined,
      );
    }

    // Validate all required Arcium accounts
    assertValidArciumAccounts(arciumAccounts);

    // Generate random MPC callback data offset
    const mpcCallbackDataOffset = generateRandomU128();

    // ================================================================
    // Step 5: Build the withdrawal instruction
    // ================================================================

    let instruction: Instruction;

    // Protocol fee provider for withdrawal category
    const protocolFeeProvider = getHardcodedWithdrawalProtocolFeeProvider();
    const protocolFeeConfig = await protocolFeeProvider(withdrawalAmount);

    try {
      const noopSigner = createNoopSigner(signer.address);
      instruction = await getWithdrawFromSharedBalanceIntoPublicBalanceV11InstructionAsync({
        // Signers
        userAddress: noopSigner,
        feePayer: noopSigner,
        // Arcium accounts
        mxeAccount: arciumAccounts.mxeAccount,
        mempoolAccount: arciumAccounts.mempoolAccount,
        executingPool: arciumAccounts.executingPoolAccount,
        computationAccount: arciumAccounts.computationAccount,
        compDefAccount: arciumAccounts.compDefAccount,
        clusterAccount: arciumAccounts.clusterAccount,
        // Token mint and program
        mint,
        tokenProgram: mintTokenProgram,
        // Instruction data
        computationOffset: {
          first: computationOffset,
        },
        feeVaultOffset: {
          first: 0n,
        },
        mpcCallbackDataOffset: {
          first: mpcCallbackDataOffset,
        },
        withdrawalAmount: {
          first: withdrawalAmount,
        },
        priorityFees: { first: microLamportsPerAcu },
        optionalData: {
          first: optionalData,
        },
        // Fee slab data and merkle proof
        ...feeSlabResultToInstructionFields(protocolFeeConfig),
      }, { programAddress: client.networkConfig.programId });
    } catch (error) {
      if (error instanceof EncryptedWithdrawalError) {
        throw error;
      }
      throw new EncryptedWithdrawalError(
        "instruction-build",
        `Failed to build withdrawal instruction: ${error instanceof Error ? error.message : String(error)}`,
        error instanceof Error ? error : undefined,
      );
    }

    // Validate instruction was created

     
    if (instruction === undefined || instruction === null) {
      throw new EncryptedWithdrawalError(
        "instruction-build",
        "getWithdrawFromSharedBalanceIntoPublicBalanceV11InstructionAsync returned null or undefined",
      );
    }

    // ================================================================
    // Step 6: Execute transaction
    // ================================================================

    const resolvedAwaitConfig =
      factoryAwaitComputationFinalization === false
        ? false
        : (factoryAwaitComputationFinalization ?? {});
    const callbackOptions: AwaitCallbackOptions | undefined =
      resolvedAwaitConfig === false
        ? undefined
        : {
            ...resolvedAwaitConfig,
            retrieveCallbackSignature: true,
            computationAccountAddress: arciumAccounts.computationAccount,
            computationOffset: BigInt(computationOffset),
            clusterOffset: clusterOffset,
          };

    return executeTransaction(instruction, clusterOffset, callbackOptions);
  };
}
