/**
 * Encrypted User Account Fetcher Implementation
 *
 * This module provides the implementation for fetching and decoding
 * Arcium encrypted user accounts from the Solana blockchain.
 *
 * @remarks
 * ## The EncryptedUserAccount
 *
 * Every Umbra user has a single `EncryptedUserAccount` PDA, derived from
 * their wallet address (`[EncryptedUserAccount::SEED, userWallet]`). This
 * account is the root of the user's protocol identity and stores:
 *
 * - **`x25519PublicKeyForMasterViewingKeyEncryption`**: The user's Master Viewing Key X25519 public key.
 *   This is the identity anchor for all compliance grant operations. The
 *   corresponding private key is never stored on-chain; it is derived from the
 *   user's master seed client-side.
 *
 * - **`userCommitment`**: A Poseidon hash commitment to a secret binary tree
 *   that encodes the user's ZK keys (master viewing key, shielding private key,
 *   etc.). Required to participate in anonymous/mixer transactions.
 *
 * - **`generationIndex`**: A monotonically increasing counter used for
 *   deterministic nonce derivation. Incremented when new token accounts are
 *   initialised or existing ones are converted from MXE to Shared mode.
 *
 * - **`randomGenerationSeed`**: A 32-byte entropy seed contributing to nonce
 *   derivation. Rotatable by the user via `update_random_generation_seed`.
 *
 * - **Status flags** (`statusBits`): Parsed as four booleans:
 *   - `isInitialised` — whether the account has been set up
 *   - `isActiveForAnonymousUsage` — anonymous (UTXO/mixer) transactions enabled
 *   - `isUserCommitmentRegistered` — ZK commitment set
 *   - `isX25519PubkeyRegistered` — X25519 key registered (enables Shared mode)
 *
 * ## Codama Type Unwrapping
 *
 * The Codama-generated decoder wraps each field in a `{ first: T }` object to
 * handle Solana's fixed-size array representation. The internal `convertToSdkTypes`
 * function unwraps these to the SDK's branded types:
 * - `{ first: number }` → `U8` (version byte, bump)
 * - `{ first: bigint }` → `U128` (generation index) or `U8` (status bits raw)
 * - `{ first: ReadonlyUint8Array }` → `X25519PublicKey`, `U256LeBytes`
 * - `PoseidonHash` bytes (32-byte little-endian bigint) → `PoseidonHash` (`bigint`)
 *
 * ## Usage Pattern
 *
 * The returned function accepts a `userAddress` parameter (not necessarily the
 * client's own address), allowing it to be used to inspect any Umbra user's
 * public account state. However, fields like `randomGenerationSeed` are
 * meaningful only to the account owner who holds the corresponding master seed.
 *
 * @packageDocumentation
 * @module implementation/umbra/services/query/user-account
 */

import type { Address, MaybeEncodedAccount } from "@solana/kit";
import {
  decodeEncryptedUserAccount,
  type EncryptedUserAccount as CodamaUserAccount,
} from "@umbra-privacy/umbra-codama";
import type {
  QueryUserAccountFunction,
  GetQueryUserAccountFunctionArgs,
  GetQueryUserAccountFunctionDeps,
} from "../../interfaces";
import type { EncryptedUserAccount, QueryUserAccountResult } from "../../types";
import type { PoseidonHash, X25519PublicKey } from "../../../types/cryptography";
import type { U128, U256LeBytes, U8 } from "../../../common/types";
import { findEncryptedUserAccountPda } from "../../../common/pda/user";
import { getByteAt } from "../../../common/type-helpers";
import { QueryError } from "../../../errors";

/* =============================================================================
 * STATUS BIT PARSING
 * ============================================================================= */

/**
 * Parses status bits from the raw `statusBits.first` bigint value in the
 * Codama-decoded account.
 *
 * @remarks
 * The on-chain status bits field is a packed `u64` where each bit represents
 * a boolean flag. The bit positions and their meanings are:
 * - Bit 0: `is_initialised` — the account has been fully initialised
 * - Bit 1: `is_active_for_anonymous_usage` — anonymous/UTXO transactions enabled
 * - Bit 2: `is_user_commitment_registered` — ZK user commitment has been set
 * - Bit 3: `is_x25519_pubkey_registered` — X25519 MVK public key has been set
 *
 * @param statusBits - The raw packed status bits value from the Codama decoder.
 * @returns An object with four boolean fields corresponding to the four status
 *   flags currently in use.
 *
 * @internal
 */
function parseStatusBits(statusBits: bigint): {
  isInitialised: boolean;
  isActiveForAnonymousUsage: boolean;
  isUserCommitmentRegistered: boolean;
  isUserAccountX25519KeyRegistered: boolean;
} {
  return {
    isInitialised: (statusBits & (1n << 0n)) !== 0n,
    isActiveForAnonymousUsage: (statusBits & (1n << 1n)) !== 0n,
    isUserCommitmentRegistered: (statusBits & (1n << 2n)) !== 0n,
    isUserAccountX25519KeyRegistered: (statusBits & (1n << 4n)) !== 0n,
  };
}

/**
 * Converts a little-endian byte array to a bigint.
 *
 * @remarks
 * Several fields in the `EncryptedUserAccount` (e.g. `userCommitment`)
 * are serialised as 32-byte little-endian values. This function reconstructs
 * the canonical `bigint` representation required by the SDK's branded types.
 *
 * Handles both `Uint8Array` instances and arbitrary `ArrayLike<number>` objects
 * (e.g. the `ReadonlyUint8Array` type produced by the Codama decoder).
 *
 * @param bytes - The byte array in little-endian format.
 * @returns The reconstructed `bigint` value.
 *
 * @internal
 */
function bytesToBigIntLe(bytes: Uint8Array | ArrayLike<number>): bigint {
  // Convert to Uint8Array if it's an ArrayLike (e.g., ReadonlyUint8Array from codama)
  const array = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  // Convert little-endian bytes to bigint
  let result = 0n;
  const length = array.length;
  for (let index = length - 1; index >= 0; index--) {
    const byte = getByteAt(array, index);
    result = (result << 8n) | BigInt(byte);
  }
  return result;
}

/* =============================================================================
 * ACCOUNT DATA CONVERSION
 * ============================================================================= */

/**
 * Converts Codama-decoded account data to the SDK's `EncryptedUserAccount` type.
 *
 * @remarks
 * The Codama types use wrapper objects with a `first` property for every field,
 * which reflects the on-chain fixed-size array encoding:
 * - `VersionByte = { first: number }`
 * - `CanonicalBump = { first: number }`
 * - `StatusBits = { first: bigint }`
 * - `ArciumX25519PublicKey = { first: ReadonlyUint8Array }`
 * - `PoseidonHash = { first: ReadonlyUint8Array }` (32-byte little-endian)
 * - `NonceGenerationIndex = { first: bigint }`
 * - `RandomGenerationSeed = { first: ReadonlyUint8Array }`
 *
 * This function:
 * - Unwraps all `{ first: T }` wrappers.
 * - Parses the `statusBits` bigint into named boolean flags via `parseStatusBits`.
 * - Converts the 32-byte little-endian `userCommitment` bytes to a `PoseidonHash` bigint.
 * - Casts numeric values to the appropriate SDK branded types (`U8`, `U128`).
 *
 * @param codamaAccount - The raw account data object returned by the Codama
 *   `decodeEncryptedUserAccount` function.
 * @returns An `EncryptedUserAccount` object using SDK branded types with parsed
 *   status flags.
 *
 * @internal
 */
function convertToSdkTypes(codamaAccount: CodamaUserAccount): EncryptedUserAccount {
  // Extract values from codama wrapper types
  const statusBitsValue = codamaAccount.statusBits.first;
  const statusFlags = parseStatusBits(statusBitsValue);

  // Convert PoseidonHash bytes to bigint (stored as 32-byte little-endian)
  const userCommitmentBigInt = bytesToBigIntLe(codamaAccount.userCommitment.first);

  return {
    versionByte: BigInt(codamaAccount.versionByte.first) as U8,
    canonicalBump: BigInt(codamaAccount.canonicalBump.first) as U8,
    ...statusFlags,
    x25519PublicKey: new Uint8Array(codamaAccount.x25519PublicKeyForMasterViewingKeyEncryption.first) as X25519PublicKey,
    userCommitment: userCommitmentBigInt as PoseidonHash,
    generationIndex: codamaAccount.generationIndex.first as U128,
    randomGenerationSeed: new Uint8Array(codamaAccount.randomGenerationSeed.first) as U256LeBytes,
  };
}

/* =============================================================================
 * FACTORY FUNCTION
 * ============================================================================= */

/**
 * Creates a function for fetching the on-chain state of a user's encrypted user account.
 *
 * @remarks
 * This factory creates a fetcher that:
 * 1. Derives the user account PDA from the client's signer address
 * 2. Fetches the account data using the AccountInfoProvider
 * 3. Decodes the raw bytes using the codama decoder
 * 4. Converts to SDK typed structures with parsed status flags
 *
 * The returned function accepts a `userAddress` parameter so that it can
 * inspect accounts other than the client's own. For example, a relayer service
 * might use this to check whether a user has registered their X25519 key before
 * accepting a confidential transfer request.
 *
 * Dependency resolution order: explicit `deps` override takes precedence,
 * then the corresponding field on `client`.
 *
 * @param args - Factory arguments containing the Umbra client. Provides the
 *   `accountInfoProvider`, `programId`, and other network configuration.
 * @param deps - Optional dependencies; defaults derived from client if not
 *   provided. Override `accountInfoProvider` to use a custom RPC endpoint or
 *   caching layer.
 * @returns A `QueryUserAccountFunction` that fetches and decodes the encrypted
 *   user account for a given wallet address.
 *
 * @example
 * ```typescript
 * import { getQueryUserAccountFunction } from "@umbra-privacy/sdk";
 *
 * const fetchUserAccount = getQueryUserAccountFunction({ client });
 *
 * const result = await fetchUserAccount(address("8xH3..."));
 *
 * if (result.state === "exists") {
 *     console.log("X25519 registered:", result.data.isX25519PubkeyRegistered);
 *     console.log("Can use anonymous mode:", result.data.isActiveForAnonymousUsage);
 *     console.log("Generation index:", result.data.generationIndex);
 * } else {
 *     console.log("User has not registered with Umbra yet");
 * }
 * ```
 *
 * @example
 * ```typescript
 * // Check another user's registration status (e.g. before sending a transfer)
 * const recipientStatus = await fetchUserAccount(recipientWalletAddress);
 * if (recipientStatus.state === "non_existent") {
 *   throw new Error("Recipient has not registered with Umbra");
 * }
 * if (!recipientStatus.data.isX25519PubkeyRegistered) {
 *   throw new Error("Recipient cannot receive shared-mode transfers");
 * }
 * ```
 *
 * @see {@link QueryUserAccountFunction} — the type of the returned function
 * @see {@link QueryUserAccountResult} — discriminated union return type
 * @see {@link EncryptedUserAccount} — the account data type
 * @see {@link GetQueryUserAccountFunctionArgs} — factory argument type
 * @see {@link GetQueryUserAccountFunctionDeps} — injectable dependency type
 * @see {@link getQueryEncryptedBalanceFunction} — fetches per-mint encrypted balances
 * @public
 */
export function getUserAccountQuerierFunction(
  args: GetQueryUserAccountFunctionArgs,
  deps?: GetQueryUserAccountFunctionDeps,
): QueryUserAccountFunction {
  const { client } = args;
  const umbraProgram: Address = client.networkConfig.programId;
  const accountInfoProvider = deps?.accountInfoProvider ?? client.accountInfoProvider;

  /**
   * Fetches and decodes the `EncryptedUserAccount` for the given wallet address.
   *
   * @remarks
   * The PDA is derived as `[EncryptedUserAccount::SEED, userAddress]`
   * using `findEncryptedUserAccountPda`. A single `accountInfoProvider`
   * call fetches the account data, which is then decoded and converted to SDK
   * types.
   *
   * This function does not modify any state; it is a pure read operation.
   *
   * @param userAddress - The Solana wallet address of the user whose account
   *   state to query. Does not need to be the client's own wallet address.
   * @returns `{ state: "exists", data: EncryptedUserAccount }` if the account
   *   PDA exists on-chain, or `{ state: "non_existent" }` if it has not yet
   *   been initialised.
   *
   * @example
   * ```typescript
   * const result = await queryUserAccount(address("8xH3..."));
   * if (result.state === "exists") {
   *   console.log("User is registered:", result.data.isInitialised);
   * }
   * ```
   *
   * @param options - Optional. Pass `{ accountInfoCommitment }` to override the
   *   default `"confirmed"` commitment level for account reads.
   * @public
   */
  return async function queryUserAccount(userAddress: Address,
    options?: { readonly accountInfoCommitment?: "processed" | "confirmed" | "finalized" }): Promise<QueryUserAccountResult> {
    const accountInfoCommitment = options?.accountInfoCommitment ?? "confirmed";
    // Step 1: Derive the user account PDA
    let userAccountPda: Address;
    try {
      userAccountPda = await findEncryptedUserAccountPda(userAddress, umbraProgram);
    } catch (error) {
      throw new QueryError(
        "pda-derivation",
        `Failed to derive user account PDA: ${error instanceof Error ? error.message : String(error)}`,
        error instanceof Error ? error : undefined,
      );
    }

    // Step 2: Fetch the account data
    let accountMap: Awaited<ReturnType<typeof accountInfoProvider>>;
    try {
      accountMap = await accountInfoProvider([userAccountPda], { commitment: accountInfoCommitment });
    } catch (error) {
      throw new QueryError(
        "account-fetch",
        `Failed to fetch user account data: ${error instanceof Error ? error.message : String(error)}`,
        error instanceof Error ? error : undefined,
      );
    }
    const maybeAccount: MaybeEncodedAccount<Address> | undefined = accountMap.get(userAccountPda);

    // Step 3: Check if account exists

     
    if (maybeAccount === undefined || !maybeAccount.exists || maybeAccount.data === undefined) {
      return { state: "non_existent" };
    }

    // Step 4: Decode and convert account data
    let sdkAccount: EncryptedUserAccount;
    try {
      const decodedAccount = decodeEncryptedUserAccount(
        maybeAccount as MaybeEncodedAccount<Address> & {
          exists: true;
        },
      );
      sdkAccount = convertToSdkTypes(decodedAccount.data);
    } catch (error) {
      throw new QueryError(
        "account-decode",
        `Failed to decode user account data: ${error instanceof Error ? error.message : String(error)}`,
        error instanceof Error ? error : undefined,
      );
    }

    return { state: "exists", data: sdkAccount };
  };
}
